return [ 'project-id-version' => 'fluid-checkout','mime-version' => '1.0','content-type' => 'text/plain; charset=utf-8','content-transfer-encoding' => '8bit','language-team' => 'Fluid Checkout','last-translator' => 'Fluid Checkout','pot-creation-date' => '2025-03-06 01:48+0000','report-msgid-bugs-to' => 'https://fluidcheckout.com/support','x-poedit-basepath' => '..','x-poedit-keywordslist' => '__;_e;_ex:1,2c;_n:1,2;_n_noop:1,2;_nx:1,2,4c;_nx_noop:1,2,3c;_x:1,2c;esc_attr__;esc_attr_e;esc_attr_x:1,2c;esc_html__;esc_html_e;esc_html_x:1,2c','x-poedit-searchpath-0' => '.','x-poedit-searchpathexcluded-0' => '*.js','x-poedit-sourcecharset' => 'UTF-8','plural-forms' => 'nplurals=2; plural=(n != 1);','messages' => ['WooCommerce' => 'వూకామర్స్','Go to Plugin Search' => 'ప్లగిన్ శోధనకు వెళ్ళండి','Activate %s' => '%s ని యాక్టివేట్ చేయండి','<strong>%1$s</strong> requires <strong>%2$s</strong> to be installed and activated. <a href="%4$s">%3$s</a>' => '<strong>%1$s కి</strong> <strong>%2$s</strong> ఇన్‌స్టాల్ చేయబడి, యాక్టివేట్ చేయబడాలి. <a href="%4$s">%3$s</a>','Enter your code here' => 'మీ కోడ్‌ను ఇక్కడ నమోదు చేయండి','Add %s' => '%s ని జోడించండి','Remove' => 'తొలగించు','Order number and receipt will be sent to this email address.' => 'ఆర్డర్ నంబర్ మరియు రసీదు ఈ ఇమెయిల్ చిరునామాకు పంపబడతాయి.','Apartment, unit, building, floor, etc.' => 'అపార్ట్‌మెంట్, యూనిట్, భవనం, అంతస్తు మొదలైనవి.','Shipping phone' => 'షిప్పింగ్ ఫోన్','Only used for shipping-related questions.' => 'షిప్పింగ్ సంబంధిత ప్రశ్నలకు మాత్రమే ఉపయోగించబడుతుంది.','Single step' => 'సింగిల్ స్టెప్','Click to go to the order summary' => 'ఆర్డర్ సారాంశానికి వెళ్లడానికి క్లిక్ చేయండి.','Cart total:' => 'కార్ట్ మొత్తం:','Proceed to %s' => '%s కి కొనసాగండి','Proceed to contact' => 'సంప్రదింపుకు కొనసాగండి','Proceed to shipping' => 'షిప్పింగ్‌కు కొనసాగండి','Proceed to billing' => 'బిల్లింగ్‌కు వెళ్లండి','Proceed to payment' => 'చెల్లింపుకు కొనసాగండి','Shipping method' => 'షిప్పింగ్ పద్ధతి','Additional notes' => 'అదనపు గమనికలు','Payment method' => 'చెల్లింపు పద్ధతి','Step %1$s of %2$s' => '%2$s లో %1$s దశ','Change: %s' => 'మార్పు: %s','Not selected yet.' => 'ఇంకా ఎంపిక కాలేదు.','Same as shipping address' => 'షిప్పింగ్ చిరునామా లాంటిదే','Same as billing address' => 'బిల్లింగ్ చిరునామా లాంటిది','Order summary' => 'ఆర్డర్ సారాంశం','Edit cart' => 'కార్ట్‌ను సవరించు','Did you mean %s?' => 'మీరు %s అని అడిగారా?','Change email address to: {suggestion-value}' => 'ఇమెయిల్ చిరునామాను ఇలా మార్చండి: {suggestion-value}','This is a required field.' => 'ఇది తప్పనిసరి ఫీల్డ్.','This is not a valid email address.' => 'ఇది చెల్లుబాటు అయ్యే ఇమెయిల్ చిరునామా కాదు.','This field does not match the related field value.' => 'ఈ ఫీల్డ్ సంబంధిత ఫీల్డ్ విలువతో సరిపోలడం లేదు.','The CPF number "{cpf_number}" is invalid.' => 'CPF సంఖ్య &quot;{cpf_number}&quot; చెల్లదు.','The CNPJ number "{cnpj_number}" is invalid.' => 'CNPJ సంఖ్య &quot;{cnpj_number}&quot; చెల్లదు.','(Required)' => '(అవసరం)','Checkout Header - Desktop' => 'చెక్అవుట్ హెడర్ - డెస్క్‌టాప్','Display widgets on the checkout header for large screens. Only displayed if using the plugin\'s checkout header.' => 'పెద్ద స్క్రీన్‌ల కోసం చెక్అవుట్ హెడర్‌లో విడ్జెట్‌లను ప్రదర్శించండి. ప్లగిన్ చెక్అవుట్ హెడర్‌ను ఉపయోగిస్తుంటే మాత్రమే ప్రదర్శించబడుతుంది.','Checkout Header - Mobile' => 'చెక్అవుట్ హెడర్ - మొబైల్','Display widgets below the checkout header for mobile devices. Only displayed if using the plugin\'s checkout header.' => 'మొబైల్ పరికరాల కోసం చెక్అవుట్ హెడర్ కింద విడ్జెట్‌లను ప్రదర్శించు. ప్లగిన్ చెక్అవుట్ హెడర్‌ను ఉపయోగిస్తుంటే మాత్రమే ప్రదర్శించబడుతుంది.','Checkout Sidebar' => 'చెక్అవుట్ సైడ్‌బార్','Display widgets on the checkout sidebar after the order summary.' => 'ఆర్డర్ సారాంశం తర్వాత చెక్అవుట్ సైడ్‌బార్‌లో విడ్జెట్‌లను ప్రదర్శించండి.','Checkout Order Summary' => 'చెక్అవుట్ ఆర్డర్ సారాంశం','Display widgets inside the order summary at the checkout page.' => 'చెక్అవుట్ పేజీలో ఆర్డర్ సారాంశం లోపల విడ్జెట్‌లను ప్రదర్శించండి.','Checkout Below Place Order' => 'ప్లేస్ ఆర్డర్ క్రింద చెక్అవుట్ చేయండి','Display widgets below the place order button at the checkout page.' => 'చెక్అవుట్ పేజీలో ప్లేస్ ఆర్డర్ బటన్ కింద విడ్జెట్‌లను ప్రదర్శించండి.','Checkout Footer' => 'చెక్అవుట్ ఫుటర్','Display widgets on the checkout footer. Only displayed if using the plugin\'s checkout footer.' => 'చెక్అవుట్ ఫుటర్‌లో విడ్జెట్‌లను ప్రదర్శించు. ప్లగిన్ చెక్అవుట్ ఫుటర్‌ను ఉపయోగిస్తుంటే మాత్రమే ప్రదర్శించబడుతుంది.','Classic' => 'క్లాసిక్','Boxed' => 'బాక్స్డ్','Split' => 'విభజించు','Minimalist' => 'మినిమలిస్ట్','Fluid Checkout and Delivery Date plugins by CodeRockz' => 'కోడ్‌రాక్జ్ ద్వారా ఫ్లూయిడ్ చెక్అవుట్ మరియు డెలివరీ తేదీ ప్లగిన్‌లు','<p>We detected that you are using the plugins Delivery & Pickup Date Time for WooCommerce (free and PRO) by CodeRockz. Integration with these plugins have been moved to Fluid Checkout PRO.</p>' => '<p>మీరు CodeRockz ద్వారా WooCommerce (ఉచిత మరియు PRO) కోసం డెలివరీ &amp; పికప్ తేదీ సమయం ప్లగిన్‌లను ఉపయోగిస్తున్నట్లు మేము గుర్తించాము. ఈ ప్లగిన్‌లతో ఇంటిగ్రేషన్ ఫ్లూయిడ్ చెక్అవుట్ PROకి తరలించబడింది.</p>','Upgrade to PRO' => 'PRO కి అప్‌గ్రేడ్ చేయండి','Fluid Checkout database updated successfully' => 'ఫ్లూయిడ్ చెక్అవుట్ డేటాబేస్ విజయవంతంగా నవీకరించబడింది','The database changes where applied successfully.' => 'విజయవంతంగా వర్తింపజేసిన చోట డేటాబేస్ మారుతుంది.','Dismiss' => 'తీసివేయి','Fluid Checkout database update' => 'ఫ్లూయిడ్ చెక్అవుట్ డేటాబేస్ నవీకరణ','Some changes to the database are required. As with any update, we recommend you to <strong>take a full backup of your website before proceeding</strong>.' => 'డేటాబేస్‌లో కొన్ని మార్పులు అవసరం. ఏదైనా నవీకరణ మాదిరిగానే, <strong>కొనసాగే ముందు మీ వెబ్‌సైట్ యొక్క పూర్తి బ్యాకప్ తీసుకోవాలని</strong> మేము మీకు సిఫార్సు చేస్తున్నాము.','Update database' => 'డేటాబేస్‌ను నవీకరించండి','Fluid Checkout is not compatible with the Divi Builder checkout layout' => 'ఫ్లూయిడ్ చెక్అవుట్ దివి బిల్డర్ చెక్అవుట్ లేఅవుట్‌తో అనుకూలంగా లేదు.','<p>Fluid Checkout needs the classic WooCommerce shortcode-based checkout form to work. When using the Divi Builder to customize the look and feel of the checkout page, the classic shortcodes are replaced with custom widgets from the Divi Builder for each part of the checkout page. These custom widgets are not compatible with Fluid Checkout.</p><p>Please edit your checkout page replacing the Divi Builder widgets with the a text widget containing the shortcode <code>[woocommerce_checkout]</code>.</p>' => '<p>ఫ్లూయిడ్ చెక్అవుట్ పనిచేయడానికి క్లాసిక్ WooCommerce షార్ట్‌కోడ్ ఆధారిత చెక్అవుట్ ఫారమ్ అవసరం. చెక్అవుట్ పేజీ యొక్క రూపాన్ని మరియు అనుభూతిని అనుకూలీకరించడానికి డివి బిల్డర్‌ను ఉపయోగిస్తున్నప్పుడు, క్లాసిక్ షార్ట్‌కోడ్‌లు చెక్అవుట్ పేజీలోని ప్రతి భాగానికి డివి బిల్డర్ నుండి కస్టమ్ విడ్జెట్‌లతో భర్తీ చేయబడతాయి. ఈ కస్టమ్ విడ్జెట్‌లు ఫ్లూయిడ్ చెక్అవుట్‌తో అనుకూలంగా లేవు.</p><p> దయచేసి మీ చెక్అవుట్ పేజీని దివి బిల్డర్ విడ్జెట్‌ల స్థానంలో షార్ట్‌కోడ్ <code>[woocommerce_checkout]</code> ఉన్న టెక్స్ట్ విడ్జెట్‌తో సవరించండి.</p>','Edit the checkout page' => 'చెక్అవుట్ పేజీని సవరించండి','Read the documentation.' => 'డాక్యుమెంటేషన్ చదవండి.','Germanized PRO multistep checkout feature needs to be disabled when using Fluid Checkout' => 'ఫ్లూయిడ్ చెక్అవుట్ ఉపయోగిస్తున్నప్పుడు జర్మనీీకరించబడిన PRO మల్టీస్టెప్ చెక్అవుట్ ఫీచర్‌ను నిలిపివేయాలి.','When using Fluid Checkout, the multistep feature from the Germanized PRO plugin becomes unnecessary and can cause <strong>critical errors while processing new orders</strong>. Please disable the Germanized PRO multistep checkout feature in the plugin settings.' => 'ఫ్లూయిడ్ చెక్అవుట్ ఉపయోగిస్తున్నప్పుడు, జర్మనీజ్డ్ PRO ప్లగిన్ నుండి మల్టీస్టెప్ ఫీచర్ అనవసరంగా మారుతుంది మరియు <strong>కొత్త ఆర్డర్‌లను ప్రాసెస్ చేస్తున్నప్పుడు క్లిష్టమైన లోపాలకు</strong> కారణమవుతుంది. దయచేసి ప్లగిన్ సెట్టింగ్‌లలో జర్మనీజ్డ్ PRO మల్టీస్టెప్ చెక్అవుట్ ఫీచర్‌ను నిలిపివేయండి.','Go to Germanized settings' => 'జర్మనీీకరించిన సెట్టింగ్‌లకు వెళ్లండి','Thanks for choosing Fluid Checkout!' => 'ఫ్లూయిడ్ చెక్అవుట్ ఎంచుకున్నందుకు ధన్యవాదాలు!','You have been using the plugin for a while now. How do you like it so far? <br>Please give us a quick rating, we appreciate every bit of feedback and it encourages us to keep improving the plugin :)' => 'మీరు కొంతకాలంగా ప్లగిన్‌ను ఉపయోగిస్తున్నారు. ఇప్పటివరకు మీకు ఇది ఎలా నచ్చింది?<br> దయచేసి మాకు త్వరిత రేటింగ్ ఇవ్వండి, ప్రతి అభిప్రాయాన్ని మేము అభినందిస్తున్నాము మరియు ఇది ప్లగిన్‌ను మెరుగుపరచడం కొనసాగించడానికి మమ్మల్ని ప్రోత్సహిస్తుంది :)','Rate the plugin' => 'ప్లగిన్‌ను రేట్ చేయండి','I need help!' => 'నాకు సహాయం కావాలి!','Some features of WooCommerce Checkout Manager by Quadlayers might not work as expected when using it with Fluid Checkout. Read <a href="%s">our documentation</a> for more information and alternative solutions.' => 'క్వాడ్‌లేయర్స్ ద్వారా WooCommerce Checkout మేనేజర్ యొక్క కొన్ని లక్షణాలు ఫ్లూయిడ్ చెక్‌అవుట్‌తో ఉపయోగించినప్పుడు ఆశించిన విధంగా పనిచేయకపోవచ్చు. మరింత సమాచారం మరియు ప్రత్యామ్నాయ పరిష్కారాల కోసం <a href="%s">మా డాక్యుమెంటేషన్</a> చదవండి.','Read documentation' => 'డాక్యుమెంటేషన్ చదవండి','Don\'t show this again' => 'దీన్ని మళ్ళీ చూపించవద్దు','Fluid Checkout PRO' => 'ఫ్లూయిడ్ చెక్అవుట్ PRO','More design templates' => 'మరిన్ని డిజైన్ టెంప్లేట్‌లు','Optimized cart page' => 'ఆప్టిమైజ్ చేసిన కార్ట్ పేజీ','Optimized order received / thank you page' => 'ఆప్టిమైజ్ చేసిన ఆర్డర్ అందింది / ధన్యవాదాలు పేజీ','Edit cart contents at checkout page' => 'చెక్అవుట్ పేజీలో కార్ట్ కంటెంట్‌లను సవరించండి','Account matching / user matching' => 'ఖాతా సరిపోలిక / వినియోగదారు సరిపోలిక','Trust symbols on the cart and thank you pages' => 'కార్ట్ మరియు థాంక్యూ పేజీలపై చిహ్నాలను నమ్మండి','More positions for the coupon code on the checkout page' => 'చెక్అవుట్ పేజీలో కూపన్ కోడ్ కోసం మరిన్ని స్థానాలు','International phone numbers' => 'అంతర్జాతీయ ఫోన్ నంబర్లు','Gift messages and packing slips' => 'బహుమతి సందేశాలు మరియు ప్యాకింగ్ స్లిప్‌లు','Local pickup and in-store collection' => 'స్థానిక పికప్ మరియు స్టోర్‌లో సేకరణ','EU-VAT Assistant' => 'EU-VAT అసిస్టెంట్','I already have it – Hide this offer' => 'నా దగ్గర ఇప్పటికే ఉంది – ఈ ఆఫర్‌ను దాచు','Activated' => 'యాక్టివేట్ చేయబడింది','Address book' => 'చిరునామా పుస్తకం','Select an image' => 'చిత్రాన్ని ఎంచుకోండి','Cart layout' => 'కార్ట్ లేఅవుట్','Cart optimizations' => 'కార్ట్ ఆప్టిమైజేషన్‌లు','Enable cart page optimizations' => 'కార్ట్ పేజీ ఆప్టిమైజేషన్‌లను ప్రారంభించండి','Header and footer template' => 'హెడర్ మరియు ఫుటర్ టెంప్లేట్','Controls whether to use the distraction free page header and footer or keep the currently active theme\'s header and footer.' => 'పరధ్యానం లేని పేజీ హెడర్ మరియు ఫుటర్‌ను ఉపయోగించాలా లేదా ప్రస్తుతం యాక్టివ్‌గా ఉన్న థీమ్ యొక్క హెడర్ మరియు ఫుటర్‌ను ఉంచాలా వద్దా అనేదాన్ని నియంత్రిస్తుంది.','Distraction free header and footer' => 'పరధ్యానం లేని హెడర్ మరియు ఫుటర్','Theme\'s header and footer' => 'థీమ్ యొక్క హెడర్ మరియు ఫుటర్','Cart elements' => 'కార్ట్ ఎలిమెంట్స్','Make the order summary stay visible on the cart page while scrolling' => 'స్క్రోల్ చేస్తున్నప్పుడు ఆర్డర్ సారాంశం కార్ట్ పేజీలో కనిపించేలా చేయండి.','Coupon codes' => 'కూపన్ కోడ్‌లు','Hidden' => 'దాచబడింది','Before the cart items section' => 'కార్ట్ వస్తువుల విభాగానికి ముందు','Inside the cart items section' => 'కార్ట్ ఐటెమ్స్ విభాగం లోపల','After the cart items section' => 'కార్ట్ వస్తువుల విభాగం తర్వాత','Before the shipping section' => 'షిప్పింగ్ విభాగానికి ముందు','After the shipping section' => 'షిప్పింగ్ విభాగం తర్వాత','Before the order summary' => 'ఆర్డర్ సారాంశం ముందు','Inside the order summary' => 'ఆర్డర్ సారాంశం లోపల','Before the order totals' => 'ఆర్డర్ మొత్తాలు రాకముందే','After the order totals' => 'ఆర్డర్ మొత్తాలు తర్వాత','After the order summary' => 'ఆర్డర్ సారాంశం తర్వాత','Shipping' => 'షిప్పింగ్','Select position where to display the shipping costs and calculator on the cart page.' => 'కార్ట్ పేజీలో షిప్పింగ్ ఖర్చులు మరియు కాలిక్యులేటర్‌ను ఎక్కడ ప్రదర్శించాలో స్థానాన్ని ఎంచుకోండి.','Display as a cart section' => 'కార్ట్ విభాగంగా ప్రదర్శించు','Cross-sells' => 'క్రాస్-సేల్స్','Select position where to display the cross-sells section on the cart page.' => 'కార్ట్ పేజీలో క్రాస్-సెల్ల్స్ విభాగాన్ని ఎక్కడ ప్రదర్శించాలో స్థానాన్ని ఎంచుకోండి.','Before the cart actions' => 'కార్ట్ చర్యలకు ముందు','After the cart actions' => 'కార్ట్ చర్యల తర్వాత','Layout of cross-sell items on the cart page.' => 'కార్ట్ పేజీలో క్రాస్-సెల్ వస్తువుల లేఅవుట్.','Optimized horizontal cross-sells layout' => 'ఆప్టిమైజ్ చేయబడిన క్షితిజ సమాంతర క్రాస్-సెల్స్ లేఅవుట్','Theme\'s cross-sells layout' => 'థీమ్ యొక్క క్రాస్-సెల్ల్స్ లేఅవుట్','Number of cross-sell items to display on the cart page' => 'కార్ట్ పేజీలో ప్రదర్శించాల్సిన క్రాస్-సెల్ ఐటెమ్‌ల సంఖ్య','Add widget areas to the cart page' => 'కార్ట్ పేజీకి విడ్జెట్ ప్రాంతాలను జోడించండి','These widget areas are used to add trust symbols and trust badges on the cart page.' => 'ఈ విడ్జెట్ ప్రాంతాలు కార్ట్ పేజీలో ట్రస్ట్ చిహ్నాలు మరియు ట్రస్ట్ బ్యాడ్జ్‌లను జోడించడానికి ఉపయోగించబడతాయి.','Checkout' => 'చెక్అవుట్','Checkout layout' => 'చెక్అవుట్ లేఅవుట్','Design template' => 'డిజైన్ టెంప్లేట్','Dark mode' => 'డార్క్ మోడ్','Enable dark mode' => 'డార్క్ మోడ్‌ను ప్రారంభించండి','Logo image' => 'లోగో చిత్రం','Choose an image to be displayed on the checkout page header. Only applies when using the distraction free header and footer.' => 'చెక్అవుట్ పేజీ హెడర్‌లో ప్రదర్శించాల్సిన చిత్రాన్ని ఎంచుకోండి. డిస్ట్రాక్షన్ లేని హెడర్ మరియు ఫుటర్‌ని ఉపయోగిస్తున్నప్పుడు మాత్రమే వర్తిస్తుంది.','Header background color' => 'హెడర్ నేపథ్య రంగు','Choose a background color for the checkout page header. Only applies when using the distraction free header and footer.' => 'చెక్అవుట్ పేజీ హెడర్ కోసం నేపథ్య రంగును ఎంచుకోండి. పరధ్యానం లేని హెడర్ మరియు ఫుటర్‌ను ఉపయోగిస్తున్నప్పుడు మాత్రమే వర్తిస్తుంది.','HTML color value. ie: #f3f3f3' => 'HTML రంగు విలువ. అంటే: #f3f3f3','Page background color' => 'పేజీ నేపథ్య రంగు','Choose a background color for the checkout page. Color is applied to the <em>body</em> element.' => 'చెక్అవుట్ పేజీ కోసం నేపథ్య రంగును ఎంచుకోండి. రంగు <em>ప్రధాన</em> మూలకానికి వర్తించబడుతుంది.','Footer background color' => 'ఫుటర్ నేపథ్య రంగు','Choose a background color for the checkout page footer. Only applies when using the distraction free header and footer.' => 'చెక్అవుట్ పేజీ ఫుటర్ కోసం నేపథ్య రంగును ఎంచుకోండి. పరధ్యానం లేని హెడర్ మరియు ఫుటర్‌ను ఉపయోగిస్తున్నప్పుడు మాత్రమే వర్తిస్తుంది.','Progress bar' => 'ప్రోగ్రెస్ బార్','Display the checkout progress bar when using multi-step checkout layout' => 'బహుళ-దశల చెక్అవుట్ లేఅవుట్‌ను ఉపయోగిస్తున్నప్పుడు చెక్అవుట్ ప్రోగ్రెస్ బార్‌ను ప్రదర్శించండి','Make the checkout progress bar stay visible while scrolling' => 'స్క్రోల్ చేస్తున్నప్పుడు చెక్అవుట్ ప్రోగ్రెస్ బార్ కనిపించేలా చేయండి','Express checkout' => 'ఎక్స్‌ప్రెస్ చెక్అవుట్','Enable the express checkout section' => 'ఎక్స్‌ప్రెస్ చెక్అవుట్ విభాగాన్ని ప్రారంభించండి','Displays the express checkout section at checkout when supported payment gateways have this feature enabled.' => 'మద్దతు ఉన్న చెల్లింపు గేట్‌వేలు ఈ లక్షణాన్ని ప్రారంభించినప్పుడు చెక్అవుట్ వద్ద ఎక్స్‌ప్రెస్ చెక్అవుట్ విభాగాన్ని ప్రదర్శిస్తుంది.','Display express checkout buttons in one line for larger screens' => 'పెద్ద స్క్రీన్‌ల కోసం ఎక్స్‌ప్రెస్ చెక్అవుట్ బటన్‌లను ఒకే లైన్‌లో ప్రదర్శించండి','Ignore additional checkout required fields when paying with a compatible express checkout payment gateway' => 'అనుకూలమైన ఎక్స్‌ప్రెస్ చెక్అవుట్ చెల్లింపు గేట్‌వేతో చెల్లించేటప్పుడు అదనపు చెక్అవుట్ అవసరమైన ఫీల్డ్‌లను విస్మరించండి.','Make the order summary stay visible while scrolling' => 'స్క్రోల్ చేస్తున్నప్పుడు ఆర్డర్ సారాంశం కనిపించేలా చేయండి','Choose a background color for the order summary section.' => 'ఆర్డర్ సారాంశం విభాగానికి నేపథ్య రంగును ఎంచుకోండి.','Highlight the order totals row in the order summary table' => 'ఆర్డర్ సారాంశ పట్టికలో ఆర్డర్ మొత్తాల వరుసను హైలైట్ చేయండి.','Most useful when the order summary section does not have a highlighted background color. Might also apply to the Cart, Order Received and View Order pages when using Fluid Checkout PRO.' => 'ఆర్డర్ సారాంశం విభాగంలో హైలైట్ చేయబడిన నేపథ్య రంగు లేనప్పుడు చాలా ఉపయోగకరంగా ఉంటుంది. ఫ్లూయిడ్ చెక్అవుట్ PROని ఉపయోగిస్తున్నప్పుడు కార్ట్, ఆర్డర్ రిసీవ్డ్ మరియు వ్యూ ఆర్డర్ పేజీలకు కూడా వర్తించవచ్చు.','Action link on the order summary at checkout.' => 'చెక్అవుట్ వద్ద ఆర్డర్ సారాంశంపై చర్య లింక్.','Edit cart link' => 'కార్ట్ లింక్‌ను సవరించు','Cart items count' => 'కార్ట్ వస్తువుల సంఖ్య','Link to shop page' => 'షాప్ పేజీకి లింక్ చేయండి','Cart items' => 'కార్ట్ అంశాలు','Hide cart items errors at the checkout page' => 'చెక్అవుట్ పేజీలో కార్ట్ ఐటెమ్‌ల లోపాలను దాచండి','Do not display the cart items errors message at the top of the checkout page. When submitting the checkout form to complete the purchase, these error messages will always be displayed.' => 'చెక్అవుట్ పేజీ ఎగువన కార్ట్ ఐటెమ్‌ల ఎర్రర్ సందేశాన్ని ప్రదర్శించవద్దు. కొనుగోలును పూర్తి చేయడానికి చెక్అవుట్ ఫారమ్‌ను సమర్పించేటప్పుడు, ఈ ఎర్రర్ సందేశాలు ఎల్లప్పుడూ ప్రదర్శించబడతాయి.','Place order' => 'ఆర్డర్ చేయండి','Define the position to display "Place order" and terms checkbox section.' => '&quot;క్రమాన్ని ఉంచండి&quot; మరియు నిబంధనల చెక్‌బాక్స్ విభాగాన్ని ప్రదర్శించాల్సిన స్థానాన్ని నిర్వచించండి.','Some options might not be compatible with some plugins and themes.' => 'కొన్ని ఎంపికలు కొన్ని ప్లగిన్‌లు మరియు థీమ్‌లతో అనుకూలంగా ఉండకపోవచ్చు.','Below the payment section' => 'చెల్లింపు విభాగం కింద','Below the order summary' => 'ఆర్డర్ సారాంశం క్రింద','Both below the payment section and the order summary' => 'చెల్లింపు విభాగం మరియు ఆర్డర్ సారాంశం కింద రెండూ','Add widget areas to the checkout page' => 'చెక్అవుట్ పేజీకి విడ్జెట్ ప్రాంతాలను జోడించండి','These widget areas are used to add trust symbols and trust badges on the checkout page.' => 'ఈ విడ్జెట్ ప్రాంతాలు చెక్అవుట్ పేజీలో ట్రస్ట్ చిహ్నాలు మరియు ట్రస్ట్ బ్యాడ్జ్‌లను జోడించడానికి ఉపయోగించబడతాయి.','Display the coupon codes section title' => 'కూపన్ కోడ్‌ల విభాగం శీర్షికను ప్రదర్శించండి','Select position where to display the coupon codes section on the checkout page.' => 'చెక్అవుట్ పేజీలో కూపన్ కోడ్‌ల విభాగాన్ని ఎక్కడ ప్రదర్శించాలో స్థానాన్ని ఎంచుకోండి.','Before the checkout steps' => 'చెక్అవుట్ దశలకు ముందు','As a substep before payment methods' => 'చెల్లింపు పద్ధతులకు ముందు ఉపదశగా','As a substep after payment methods' => 'చెల్లింపు పద్ధతుల తర్వాత ఉప దశగా','Default button style' => 'డిఫాల్ట్ బటన్ శైలి','"Add" link button' => '&quot;జోడించు&quot; లింక్ బటన్','Checkout fields' => 'చెక్అవుట్ ఫీల్డ్‌లు','Optional fields' => 'ఐచ్ఛిక ఫీల్డ్‌లు','Hide optional fields behind a link button' => 'లింక్ బటన్ వెనుక ఉన్న ఐచ్ఛిక ఫీల్డ్‌లను దాచు','It is recommended to keep this option checked to reduce the number of open input fields, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#1-address-line-2--company-name-can-safely-be-collapsed-behind-a-link" target="_blank">read the research</a>.' => 'ఓపెన్ ఇన్‌పుట్ ఫీల్డ్‌ల సంఖ్యను తగ్గించడానికి ఈ ఎంపికను తనిఖీ చేయాలని సిఫార్సు చేయబడింది, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#1-address-line-2--company-name-can-safely-be-collapsed-behind-a-link" target="_blank">పరిశోధన చదవండి</a> .','Do not hide "Address line 2" fields behind a link button' => 'లింక్ బటన్ వెనుక &quot;చిరునామా పంక్తి 2&quot; ఫీల్డ్‌లను దాచవద్దు.','Recommended only when most customers actually need the "Address line 2" field, or when getting the right shipping address is crucial (ie. if delivering food and other perishable products).' => 'చాలా మంది కస్టమర్లకు &quot;చిరునామా పంక్తి 2&quot; ఫీల్డ్ నిజంగా అవసరమైనప్పుడు లేదా సరైన షిప్పింగ్ చిరునామాను పొందడం చాలా ముఖ్యమైనప్పుడు (అంటే ఆహారం మరియు ఇతర పాడైపోయే ఉత్పత్తులను డెలివరీ చేస్తుంటే) మాత్రమే సిఫార్సు చేయబడింది.','Billing address' => 'బిల్లింగ్ చిరునామా','Select position where to display the billing address section on the checkout page.' => 'చెక్అవుట్ పేజీలో బిల్లింగ్ చిరునామా విభాగాన్ని ఎక్కడ ప్రదర్శించాలో స్థానాన్ని ఎంచుకోండి.','As a step before shipping' => 'షిప్పింగ్ కు ముందు ఒక అడుగుగా','As a sub-step before the shipping address section' => 'షిప్పింగ్ చిరునామా విభాగానికి ముందు ఉప దశగా','As a sub-step after the shipping address section' => 'షిప్పింగ్ చిరునామా విభాగం తర్వాత ఉప-దశగా','As a step after shipping' => 'షిప్పింగ్ తర్వాత ఒక అడుగుగా','As a sub-step before the payment section' => 'చెల్లింపు విభాగానికి ముందు ఉప దశగా','Force billing and shipping addresses to the same (single section)' => 'బిల్లింగ్ మరియు షిప్పింగ్ చిరునామాలను ఒకే (ఒకే విభాగం)కి బలవంతం చేయండి','Checkbox for "Same as shipping/billing address" checked by default' => '&quot;షిప్పింగ్/బిల్లింగ్ చిరునామా లాంటిది&quot; కోసం చెక్‌బాక్స్ డిఫాల్ట్‌గా ఎంచుకోబడింది.','The checkbox "Same as shiping address" will start as checked by default when the shipping address section is displayed first. <br>The checkbox "Same as billing address" will start as checked by default when the billing address section is displayed first. <br> It is recommended to leave this option checked as to significantly reduce the number of open input fields at checkout, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#3-default-billing--shipping-and-hide-the-fields-entirely" target="_blank">read the research</a>.' => 'షిప్పింగ్ చిరునామా విభాగం మొదట ప్రదర్శించబడినప్పుడు &quot;షిప్పింగ్ చిరునామా లాంటిదే&quot; అనే చెక్‌బాక్స్ డిఫాల్ట్‌గా ఎంచుకున్నట్లుగా ప్రారంభమవుతుంది.<br> బిల్లింగ్ చిరునామా విభాగం మొదట ప్రదర్శించబడినప్పుడు &quot;బిల్లింగ్ చిరునామా వలె&quot; అనే చెక్‌బాక్స్ డిఫాల్ట్‌గా ఎంచుకున్నట్లుగా ప్రారంభమవుతుంది.<br> చెక్అవుట్ వద్ద ఓపెన్ ఇన్‌పుట్ ఫీల్డ్‌ల సంఖ్యను గణనీయంగా తగ్గించడానికి ఈ ఎంపికను తనిఖీ చేయమని సిఫార్సు చేయబడింది, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#3-default-billing--shipping-and-hide-the-fields-entirely" target="_blank">పరిశోధన చదవండి</a> .','Highlight the billing address section in the checkout form' => 'చెక్అవుట్ ఫారమ్‌లో బిల్లింగ్ చిరునామా విభాగాన్ని హైలైట్ చేయండి.','Shipping address' => 'షిప్పింగ్ చిరునామా','Highlight the shipping address section in the checkout form' => 'చెక్అవుట్ ఫారమ్‌లో షిప్పింగ్ చిరునామా విభాగాన్ని హైలైట్ చేయండి.','Shipping methods' => 'షిప్పింగ్ పద్ధతులు','Choose in which position to display the shipping methods section.' => 'షిప్పింగ్ పద్ధతుల విభాగాన్ని ఏ స్థానంలో ప్రదర్శించాలో ఎంచుకోండి.','Before shipping address' => 'షిప్పింగ్ ముందు చిరునామా','After shipping address' => 'షిప్పింగ్ తర్వాత చిరునామా','Local pickup' => 'స్థానిక పికప్','Removes shipping address section when a local pickup shipping method is selected.' => 'స్థానిక పికప్ షిప్పింగ్ పద్ధతిని ఎంచుకున్నప్పుడు షిప్పింగ్ చిరునామా విభాగాన్ని తొలగిస్తుంది.','Replaces the shipping address with the pickup point location when a local pickup shipping method is selected.' => 'స్థానిక పికప్ షిప్పింగ్ పద్ధతిని ఎంచుకున్నప్పుడు షిప్పింగ్ చిరునామాను పికప్ పాయింట్ స్థానంతో భర్తీ చేస్తుంది.','Choose which address to save as the shipping address for local pickup orders.' => 'స్థానిక పికప్ ఆర్డర్‌ల కోసం షిప్పింగ్ చిరునామాగా ఏ చిరునామాను సేవ్ చేయాలో ఎంచుకోండి.','Save the selected pickup location' => 'ఎంచుకున్న పికప్ స్థానాన్ని సేవ్ చేయండి','Save same as the billing address' => 'బిల్లింగ్ చిరునామా లాగానే సేవ్ చేయండి','Do not save any shipping address' => 'ఏ షిప్పింగ్ చిరునామాను సేవ్ చేయవద్దు.','Company name field for shipping address' => 'షిప్పింగ్ చిరునామా కోసం కంపెనీ పేరు ఫీల్డ్','Change visibility for the company name field for the shipping address section on the checkout form.' => 'చెక్అవుట్ ఫారమ్‌లోని షిప్పింగ్ చిరునామా విభాగం కోసం కంపెనీ పేరు ఫీల్డ్ కోసం దృశ్యమానతను మార్చండి.','If field is set as "optional", which is the default visibility state, no changes will be applied to let other plugins apply any changes they need.' => 'ఫీల్డ్ &quot;ఐచ్ఛికం&quot;గా సెట్ చేయబడితే, అది డిఫాల్ట్ దృశ్యమానత స్థితి, ఇతర ప్లగిన్‌లు వారికి అవసరమైన ఏవైనా మార్పులను వర్తింపజేయడానికి ఎటువంటి మార్పులు వర్తించవు.','Hidden (remove field)' => 'దాచబడింది (ఫీల్డ్‌ను తీసివేయండి)','Optional' => 'ఐచ్ఛికం','Required' => 'అవసరం','Add shipping phone field to the checkout form.' => 'చెక్అవుట్ ఫారమ్‌కు షిప్పింగ్ ఫోన్ ఫీల్డ్‌ను జోడించండి.','Choose in which step to display the shipping phone field.' => 'షిప్పింగ్ ఫోన్ ఫీల్డ్‌ను ఏ దశలో ప్రదర్శించాలో ఎంచుకోండి.','Contact step' => 'సంప్రదింపు దశ','Billing phone' => 'బిల్లింగ్ ఫోన్','Add billing phone field to the checkout form.' => 'చెక్అవుట్ ఫారమ్‌కు బిల్లింగ్ ఫోన్ ఫీల్డ్‌ను జోడించండి.','Choose in which step to display the billing phone field.' => 'బిల్లింగ్ ఫోన్ ఫీల్డ్‌ను ఏ దశలో ప్రదర్శించాలో ఎంచుకోండి.','Show country code beside the flag' => 'జెండా పక్కన దేశం కోడ్‌ను చూపించు','Show an example of a valid phone number inside phone fields' => 'ఫోన్ ఫీల్డ్‌ల లోపల చెల్లుబాటు అయ్యే ఫోన్ నంబర్ యొక్క ఉదాహరణను చూపించు.','Do not change placeholders' => 'ప్లేస్‌హోల్డర్‌లను మార్చవద్దు','Show if not defined' => 'నిర్వచించకపోతే చూపించు','Always show' => 'ఎల్లప్పుడూ చూపించు','Order notes' => 'ఆర్డర్ నోట్స్','Define the visibility of the additional order notes field.' => 'అదనపు ఆర్డర్ నోట్స్ ఫీల్డ్ యొక్క దృశ్యమానతను నిర్వచించండి.','Gift options' => 'బహుమతి ఎంపికలు','Allow customers to add a gift message and other gift related options to the order.' => 'కస్టమర్‌లు ఆర్డర్‌కు బహుమతి సందేశం మరియు ఇతర బహుమతి సంబంధిత ఎంపికలను జోడించడానికి అనుమతించండి.','Display the gift message as part of the order details table instead of a separate section' => 'బహుమతి సందేశాన్ని ప్రత్యేక విభాగానికి బదులుగా ఆర్డర్ వివరాల పట్టికలో భాగంగా ప్రదర్శించండి.','This option affects the order confirmation page (thank you page) and order details on account pages, emails and packing slips.' => 'ఈ ఎంపిక ఆర్డర్ నిర్ధారణ పేజీ (ధన్యవాదాలు పేజీ) మరియు ఖాతా పేజీలు, ఇమెయిల్‌లు మరియు ప్యాకింగ్ స్లిప్‌లలోని ఆర్డర్ వివరాలను ప్రభావితం చేస్తుంది.','Account matching' => 'ఖాతా మ్యాచింగ్','Enable the account matching feature' => 'ఖాతా సరిపోలిక ఫీచర్‌ను ప్రారంభించండి','Associate the guest customer\'s orders with their existing account when an account already exists with the customer\'s contact details.' => 'కస్టమర్ యొక్క సంప్రదింపు వివరాలతో ఖాతా ఇప్పటికే ఉన్నప్పుడు అతిథి కస్టమర్ ఆర్డర్‌లను వారి ప్రస్తుత ఖాతాతో అనుబంధించండి.','Display message when an account exists with the email address provided' => 'అందించిన ఇమెయిల్ చిరునామాతో ఖాతా ఉన్నప్పుడు సందేశాన్ని ప్రదర్శించు','Replaces the account creation fields with a notification and option to log in. In some contexts, it might be recommended to leave this option disabled to protect the privacy of customers.' => 'ఖాతా సృష్టి ఫీల్డ్‌లను నోటిఫికేషన్ మరియు లాగిన్ ఎంపికతో భర్తీ చేస్తుంది. కొన్ని సందర్భాలలో, కస్టమర్ల గోప్యతను కాపాడటానికి ఈ ఎంపికను నిలిపివేయమని సిఫార్సు చేయవచ్చు.','Dashboard' => 'డాష్‌బోర్డ్','Integrations' => 'ఇంటిగ్రేషన్లు','License keys' => 'లైసెన్స్ కీలు','Visit our website for more information about our plugins and add-ons.' => 'మా ప్లగిన్లు మరియు యాడ్-ఆన్‌ల గురించి మరింత సమాచారం కోసం మా వెబ్‌సైట్‌ను సందర్శించండి.','Order pay page' => 'ఆర్డర్ చెల్లింపు పేజీ','Order pay' => 'ఆర్డర్ పే','Enable order pay page optimizations' => 'ఆర్డర్ పే పేజీ ఆప్టిమైజేషన్‌లను ప్రారంభించండి','Changes the layout of order pay page for existing orders pending payment from the customer.' => 'కస్టమర్ నుండి చెల్లింపు పెండింగ్‌లో ఉన్న ఆర్డర్‌ల కోసం ఆర్డర్ చెల్లింపు పేజీ యొక్క లేఅవుట్‌ను మారుస్తుంది.','Add widget areas to the order pay page' => 'ఆర్డర్ చెల్లింపు పేజీకి విడ్జెట్ ప్రాంతాలను జోడించండి','These widget areas are used to add trust symbols and trust badges on the order pay page.' => 'ఆర్డర్ పే పేజీలో ట్రస్ట్ చిహ్నాలు మరియు ట్రస్ట్ బ్యాడ్జ్‌లను జోడించడానికి ఈ విడ్జెట్ ప్రాంతాలు ఉపయోగించబడతాయి.','Thank you page & order details layout' => 'ధన్యవాదాలు పేజీ &amp; ఆర్డర్ వివరాల లేఅవుట్','Order details optimizations' => 'ఆర్డర్ వివరాల ఆప్టిమైజేషన్‌లు','Enable thank you page and order details optimizations' => 'ధన్యవాదాలు పేజీ మరియు ఆర్డర్ వివరాల ఆప్టిమైజేషన్‌లను ప్రారంభించండి','Changes the layout of order details on the thank you page and account pages.' => 'ధన్యవాదాలు పేజీ మరియు ఖాతా పేజీలలో ఆర్డర్ వివరాల లేఅవుట్‌ను మారుస్తుంది.','Enable order details customizations on email notifications' => 'ఇమెయిల్ నోటిఫికేషన్‌లలో ఆర్డర్ వివరాల అనుకూలీకరణలను ప్రారంభించండి','Display new sections and change order of sections on email notifications. Styles of order details on email notifications remain unchanged.' => 'ఇమెయిల్ నోటిఫికేషన్‌లలో కొత్త విభాగాలను ప్రదర్శించండి మరియు విభాగాల క్రమాన్ని మార్చండి. ఇమెయిల్ నోటిఫికేషన్‌లలో ఆర్డర్ వివరాల శైలులు మారవు.','Thank you page' => 'ధన్యవాదాలు పేజీ','These options affect the thank you page, also known as order received or order confirmation pages.' => 'ఈ ఎంపికలు ధన్యవాదాలు పేజీని ప్రభావితం చేస్తాయి, వీటిని ఆర్డర్ అందుకున్న లేదా ఆర్డర్ నిర్ధారణ పేజీలు అని కూడా పిలుస్తారు.','Order details layout' => 'ఆర్డర్ వివరాల లేఅవుట్','Display the order details with wide layout on the thank you page' => 'థాంక్యూ పేజీలో ఆర్డర్ వివరాలను విస్తృత లేఅవుట్‌తో ప్రదర్శించండి.','Add widget areas to the thank you page' => 'ధన్యవాదాల పేజీకి విడ్జెట్ ప్రాంతాలను జోడించండి','These widget areas are used to add trust symbols and trust badges on the thank you page.' => 'ఈ విడ్జెట్ ప్రాంతాలు ధన్యవాదాలు పేజీలో ట్రస్ట్ చిహ్నాలు మరియు ట్రస్ట్ బ్యాడ్జ్‌లను జోడించడానికి ఉపయోగించబడతాయి.','Order actions' => 'ఆర్డర్ చర్యలు','Choose in which position to display the order actions.' => 'ఆర్డర్ చర్యలను ఏ స్థానంలో ప్రదర్శించాలో ఎంచుకోండి.','Inside the order overview' => 'ఆర్డర్ లోపల అవలోకనం','After the order overview' => 'ఆర్డర్ అవలోకనం తర్వాత','After order sections' => 'ఆర్డర్ తర్వాత విభాగాలు','Order status' => 'ఆర్డర్ స్థితి','Display the order status progress bar' => 'ఆర్డర్ స్థితి పురోగతి పట్టీని ప్రదర్శించు','Choose in which position to display the section.' => 'విభాగాన్ని ఏ స్థానంలో ప్రదర్శించాలో ఎంచుకోండి.','After the order overview and payment instructions' => 'ఆర్డర్ అవలోకనం మరియు చెల్లింపు సూచనల తర్వాత','Before the order items section' => 'ఆర్డర్ ఐటెమ్‌ల విభాగానికి ముందు','Inside the order items section' => 'ఆర్డర్ ఐటెమ్స్ విభాగం లోపల','After the order items section' => 'ఆర్డర్ ఐటెమ్‌ల విభాగం తర్వాత','On the sidebar' => 'సైడ్‌బార్‌లో','Order downloads' => 'డౌన్‌లోడ్‌లను ఆర్డర్ చేయండి','Gift message' => 'బహుమతి సందేశం','Tools' => 'ఉపకరణాలు','Troubleshooting' => 'సమస్య పరిష్కరించు','Debug options' => 'డీబగ్ ఎంపికలు','Debug mode' => 'డీబగ్ మోడ్','Using debug mode affects the website performance. Only use this option while troubleshooting.' => 'డీబగ్ మోడ్‌ని ఉపయోగించడం వల్ల వెబ్‌సైట్ పనితీరు ప్రభావితమవుతుంది. ట్రబుల్షూటింగ్ చేస్తున్నప్పుడు మాత్రమే ఈ ఎంపికను ఉపయోగించండి.','Load unminified assets' => 'కనిష్టీకరించబడని ఆస్తులను లోడ్ చేయండి','Enhanced select fields' => 'మెరుగైన ఎంపిక ఫీల్డ్‌లు','Fix automatic zoom-in on form fields' => 'ఫారమ్ ఫీల్డ్‌లలో ఆటోమేటిక్ జూమ్-ఇన్‌ను పరిష్కరించండి','Set <code>font-size</code> inside form fields to 16px' => 'ఫారమ్ ఫీల్డ్‌ల లోపల <code>font-size</code> 16pxకి సెట్ చేయండి.','Fluid Checkout' => 'ఫ్లూయిడ్ చెక్అవుట్','Settings' => 'సెట్టింగులు','Support' => 'మద్దతు','<a target="_blank" href="%s">Upgrade to PRO</a> to unlock more options.' => 'మరిన్ని ఎంపికలను అన్‌లాక్ చేయడానికి <a target="_blank" href="%s">PRO కి అప్‌గ్రేడ్ చేయండి</a> .','(PRO)' => '(ప్రో)','(experimental)' => '(ప్రయోగాత్మక)','Please verify your phone number.' => 'దయచేసి మీ ఫోన్ నంబర్‌ను ధృవీకరించండి.','The Bluehost Plugin' => 'బ్లూహోస్ట్ ప్లగిన్','Custom fields' => 'కస్టమ్ ఫీల్డ్‌లు','Enable custom shipping email field' => 'కస్టమ్ షిప్పింగ్ ఇమెయిల్ ఫీల్డ్‌ను ప్రారంభించండి','When enabled, the shipping email field from the Bluehost plugin will be added to the checkout form.' => 'ప్రారంభించినప్పుడు, బ్లూహోస్ట్ ప్లగిన్ నుండి షిప్పింగ్ ఇమెయిల్ ఫీల్డ్ చెక్అవుట్ ఫారమ్‌కు జోడించబడుతుంది.','Captcha Pro by BestWebSoft' => 'BestWebSoft ద్వారా కాప్చా ప్రో','Captcha position' => 'కాప్చా స్థానం','Define the position to display the captcha section. Some positions might not work depending on the captcha type chosen.' => 'కాప్చా విభాగాన్ని ప్రదర్శించాల్సిన స్థానాన్ని నిర్వచించండి. ఎంచుకున్న కాప్చా రకాన్ని బట్టి కొన్ని స్థానాలు పనిచేయకపోవచ్చు.','Selecting a pickup point is required before proceeding.' => 'కొనసాగే ముందు పికప్ పాయింట్‌ను ఎంచుకోవడం అవసరం.','Pickup point' => 'పికప్ పాయింట్','Pickup point not selected yet.' => 'పికప్ పాయింట్ ఇంకా ఎంచుకోబడలేదు.','Pickup point:' => 'పికప్ పాయింట్:','Mailchimp for WooCommerce' => 'WooCommerce కోసం Mailchimp','Subscribe checkbox' => 'సబ్‌స్క్రైబ్ చెక్‌బాక్స్','Override the position for the subscribe checkbox on the checkout page and always display it on the contact step' => 'చెక్అవుట్ పేజీలో సబ్‌స్క్రైబ్ చెక్‌బాక్స్ కోసం స్థానాన్ని ఓవర్‌రైడ్ చేయండి మరియు దానిని ఎల్లప్పుడూ కాంటాక్ట్ దశలో ప్రదర్శించండి.','Before Shipping Address' => 'షిప్పింగ్ ముందు చిరునామా','(originally "%s")' => '(వాస్తవానికి &quot;%s&quot;)','After Shipping Address' => 'షిప్పింగ్ తర్వాత చిరునామా','Selecting a collection point is required when shipping with FermoPoint.' => 'ఫెర్మోపాయింట్‌తో షిప్పింగ్ చేసేటప్పుడు కలెక్షన్ పాయింట్‌ను ఎంచుకోవడం అవసరం.','If checked informs typos in email to users. (This feature has been disabled because Fluid Checkout offers the feature. Changes to this option will not take effect)' => 'తనిఖీ చేయబడితే వినియోగదారులకు ఇమెయిల్‌లో టైపోగ్రాఫికల్ తప్పులు వస్తాయని తెలియజేస్తుంది. (ఫ్లూయిడ్ చెక్అవుట్ ఈ ఫీచర్‌ను అందిస్తున్నందున ఈ ఫీచర్ నిలిపివేయబడింది. ఈ ఆప్షన్‌కు మార్పులు అమలులోకి రావు)','Enable Mail Check: (disabled feature)' => 'మెయిల్ చెక్‌ను ప్రారంభించండి: (నిలిపివేయబడిన లక్షణం)','Carrier:' => 'క్యారియర్:','Sendinblue - WooCommerce Email Marketing' => 'సెండిన్ బ్లూ - WooCommerce ఇమెయిల్ మార్కెటింగ్','Sign up checkbox position' => 'సైన్ అప్ చెక్‌బాక్స్ స్థానం','Move the sign up checkbox to the contact step' => 'సైన్ అప్ చెక్‌బాక్స్‌ను కాంటాక్ట్ దశకు తరలించండి','When enabled, the checkbox will be moved to the contact step independently of the display location defined in the Sendinblue plugin settings.' => 'ప్రారంభించబడినప్పుడు, సెండిన్ బ్లూ ప్లగిన్ సెట్టింగ్‌లలో నిర్వచించిన డిస్ప్లే స్థానంతో సంబంధం లేకుండా చెక్‌బాక్స్ కాంటాక్ట్ దశకు తరలించబడుతుంది.','Theme Betheme' => 'థీమ్ బెథెమ్','Checkout progress' => 'చెక్అవుట్ పురోగతి','Output the checkout steps section from Betheme on the checkout, cart and order received pages.' => 'చెక్అవుట్, కార్ట్ మరియు ఆర్డర్ అందుకున్న పేజీలలో బెథెమ్ నుండి చెక్అవుట్ దశల విభాగాన్ని అవుట్‌పుట్ చేయండి.','Theme Fennik' => 'థీమ్ ఫెన్నిక్','Breadcrumbs' => 'బ్రెడ్‌క్రంబ్స్','Output the breadcrumbs section from the Fennik theme when using Fluid Checkout header and footer.' => 'ఫ్లూయిడ్ చెక్అవుట్ హెడర్ మరియు ఫుటర్ ఉపయోగిస్తున్నప్పుడు ఫెన్నిక్ థీమ్ నుండి బ్రెడ్‌క్రంబ్స్ విభాగాన్ని అవుట్‌పుట్ చేయండి.','Theme Go' => 'థీమ్ గో','My account layout' => 'నా ఖాతా లేఅవుట్','Enable wide layout on "My account" page.' => '&quot;నా ఖాతా&quot; పేజీలో విస్తృత లేఅవుట్‌ను ప్రారంభించండి.','Theme Impreza' => 'థీమ్ ఇంప్రెజా','Header' => 'హెడర్','Spacing for site header at the checkout page (in pixels)' => 'చెక్అవుట్ పేజీలో సైట్ హెడర్ కోసం అంతరం (పిక్సెల్‌లలో)','Only applicable when using the Impreza theme header at the checkout page.' => 'చెక్అవుట్ పేజీలో ఇంప్రెజా థీమ్ హెడర్‌ని ఉపయోగిస్తున్నప్పుడు మాత్రమే వర్తిస్తుంది.','Theme Kapee' => 'థీమ్ కాపీ','Output the checkout steps section from the Kapee theme on the checkout, cart and order received pages.' => 'చెక్అవుట్, కార్ట్ మరియు ఆర్డర్ అందుకున్న పేజీలలో కపీ థీమ్ నుండి చెక్అవుట్ దశల విభాగాన్ని అవుట్‌పుట్ చేయండి.','Theme Porto' => 'థీమ్ పోర్టో','Output the checkout steps section from the Porto theme on the checkout, cart and order received pages.' => 'చెక్అవుట్, కార్ట్ మరియు ఆర్డర్ అందుకున్న పేజీలలో పోర్టో థీమ్ నుండి చెక్అవుట్ దశల విభాగాన్ని అవుట్‌పుట్ చేయండి.','Theme Pressmart' => 'థీమ్ ప్రెస్‌మార్ట్','Output the checkout steps section from the Pressmart theme on the checkout, cart and order received pages.' => 'చెక్అవుట్, కార్ట్ మరియు ఆర్డర్ అందుకున్న పేజీలలో ప్రెస్‌మార్ట్ థీమ్ నుండి చెక్అవుట్ దశల విభాగాన్ని అవుట్‌పుట్ చేయండి.','Theme The Gem' => 'థీమ్ ది జెమ్','Output the checkout steps section from The Gem theme when using Fluid Checkout header and footer.' => 'ఫ్లూయిడ్ చెక్అవుట్ హెడర్ మరియు ఫుటర్ ఉపయోగిస్తున్నప్పుడు ది జెమ్ థీమ్ నుండి చెక్అవుట్ స్టెప్స్ విభాగాన్ని అవుట్‌పుట్ చేయండి.','Theme Woodmart' => 'థీమ్ వుడ్‌మార్ట్','Output the checkout steps section from the Woodmart theme when using Fluid Checkout header and footer.' => 'ఫ్లూయిడ్ చెక్అవుట్ హెడర్ మరియు ఫుటర్ ఉపయోగిస్తున్నప్పుడు వుడ్‌మార్ట్ థీమ్ నుండి చెక్అవుట్ స్టెప్స్ విభాగాన్ని అవుట్‌పుట్ చేయండి.','Checkout options' => 'చెక్అవుట్ ఎంపికలు','Disable the theme checkout options' => 'థీమ్ చెక్అవుట్ ఎంపికలను నిలిపివేయండి','The options display product image, quantity field, remove button and link to product page added by the theme are disabled by default.' => 'థీమ్ జోడించిన ఎంపికలు ఉత్పత్తి చిత్రాన్ని ప్రదర్శించడం, పరిమాణం ఫీల్డ్, తీసివేయి బటన్ మరియు ఉత్పత్తి పేజీకి లింక్ డిఫాల్ట్‌గా నిలిపివేయబడతాయి.','Theme Atomion' => 'థీమ్ ఆటమియన్','Order progress' => 'ఆర్డర్ పురోగతి','Display order progress from the theme' => 'థీమ్ నుండి ఆర్డర్ పురోగతిని ప్రదర్శించు','Display the form field labels visible on the page' => 'పేజీలో కనిపించే ఫారమ్ ఫీల్డ్ లేబుళ్ళను ప్రదర్శించు','It is recommended to keep this option enabled for a better user experience.' => 'మెరుగైన వినియోగదారు అనుభవం కోసం ఈ ఎంపికను ప్రారంభించి ఉంచాలని సిఫార్సు చేయబడింది.','Theme ZK Nito' => 'థీమ్ ZK నిటో','Add extra fields to the checkout form' => 'చెక్అవుట్ ఫారమ్‌కు అదనపు ఫీల్డ్‌లను జోడించండి','Adds an extra shipping email and shipping phone field to the shipping address section.' => 'షిప్పింగ్ చిరునామా విభాగానికి అదనపు షిప్పింగ్ ఇమెయిల్ మరియు షిప్పింగ్ ఫోన్ ఫీల్డ్‌ను జోడిస్తుంది.','Go to the home page' => 'హోమ్ పేజీకి వెళ్ళండి','Skip to content' => 'కంటెంట్‌కు దాటవేయి','Create an account' => 'ఒక ఖాతాను సృష్టించండి','Log in to your account' => 'మీ ఖాతాకు లాగిన్ అవ్వండి','Already have an account?' => 'ఖాతా ఉందా?','Logged in as %1$s. <a href="%2$s">Log out</a>' => '%1$s గా లాగిన్ అయ్యారు. <a href="%2$s">లాగ్ అవుట్ అవ్వండి</a>','Your order has a total amount due of %s. No further payment is needed.' => 'మీ ఆర్డర్ మొత్తం %s బకాయి ఉంది. తదుపరి చెల్లింపు అవసరం లేదు.','Close and continue with checkout' => 'మూసివేసి చెక్అవుట్ కొనసాగించండి','Continue' => 'కొనసాగించు','Parcel terminal' => 'పార్శిల్ టెర్మినల్','<p>This widget has been replaced by Fluid Checkout. </p><p>When using Fluid Checkout, the checkout page needs to use the original WooCommerce shortcode <code>[woocommerce_checkout]</code> to work properly.</p><p>For more information, visit the Fluid Checkout documentation.</p>' => '<p>ఈ విడ్జెట్ ఫ్లూయిడ్ చెక్అవుట్ ద్వారా భర్తీ చేయబడింది.</p><p> ఫ్లూయిడ్ చెక్అవుట్ ఉపయోగిస్తున్నప్పుడు, చెక్అవుట్ పేజీ సరిగ్గా పనిచేయడానికి అసలు WooCommerce షార్ట్ కోడ్ <code>[woocommerce_checkout]</code> ను ఉపయోగించాలి.</p><p> మరిన్ని వివరాలకు, ఫ్లూయిడ్ చెక్అవుట్ డాక్యుమెంటేషన్‌ను సందర్శించండి.</p>','Theme The7' => 'థీమ్ The7','Additional header sections' => 'అదనపు హెడర్ విభాగాలు','Output additional header sections if enabled in the theme settings.' => 'థీమ్ సెట్టింగ్‌లలో ఎనేబుల్ చేయబడితే అదనపు హెడర్ విభాగాలను అవుట్‌పుట్ చేయండి.','More information' => 'మరింత సమాచారం','Pick a Locker' => 'లాకర్‌ను ఎంచుకోండి','Page template' => 'పేజీ టెంప్లేట్','Use `Order confirmation` page template for block-based themes' => 'బ్లాక్ ఆధారిత థీమ్‌ల కోసం `ఆర్డర్ నిర్ధారణ` పేజీ టెంప్లేట్‌ను ఉపయోగించండి','Only applies when using a block-based theme.' => 'బ్లాక్-ఆధారిత థీమ్‌ను ఉపయోగిస్తున్నప్పుడు మాత్రమే వర్తిస్తుంది.','WooCommerce Stripe Gateway' => 'WooCommerce స్ట్రైప్ గేట్‌వే','Payment form' => 'చెల్లింపు ఫారమ్','Apply styles to the Stripe payment form fields' => 'స్ట్రైప్ చెల్లింపు ఫారమ్ ఫీల్డ్‌లకు శైలులను వర్తింపజేయండి','When enabled, Fluid Checkout will apply styles optimized for compatibility with the plugin. You may want to disable this if you are using custom styles for the Stripe payment form fields.' => 'ప్రారంభించబడినప్పుడు, ఫ్లూయిడ్ చెక్అవుట్ ప్లగిన్‌తో అనుకూలత కోసం ఆప్టిమైజ్ చేయబడిన శైలులను వర్తింపజేస్తుంది. మీరు స్ట్రైప్ చెల్లింపు ఫారమ్ ఫీల్డ్‌ల కోసం అనుకూల శైలులను ఉపయోగిస్తుంటే మీరు దీన్ని నిలిపివేయాలనుకోవచ్చు.','Theme Nyture' => 'థీమ్ నైచర్','Output the checkout steps section from the Nyture theme when using Fluid Checkout.' => 'ఫ్లూయిడ్ చెక్అవుట్ ఉపయోగిస్తున్నప్పుడు Nyture థీమ్ నుండి చెక్అవుట్ స్టెప్స్ విభాగాన్ని అవుట్‌పుట్ చేయండి.','Allows customers to make payments for orders that are either created manually by the store admin or not completed during checkout.' => 'స్టోర్ అడ్మిన్ ద్వారా మాన్యువల్‌గా సృష్టించబడిన లేదా చెక్అవుట్ సమయంలో పూర్తి కాని ఆర్డర్‌లకు చెల్లింపులు చేయడానికి కస్టమర్‌లను అనుమతిస్తుంది.','The plugin WooCommerce Checkout Manager by Quadlayers is not compatible with Fluid Checkout' => 'క్వాడ్‌లేయర్స్ ద్వారా ప్లగిన్ WooCommerce చెక్అవుట్ మేనేజర్ ఫ్లూయిడ్ చెక్అవుట్‌కు అనుకూలంగా లేదు.','Company name field for billing address' => 'బిల్లింగ్ చిరునామా కోసం కంపెనీ పేరు ఫీల్డ్','Change visibility for the company name field for the billing address section on the checkout form.' => 'చెక్అవుట్ ఫారమ్‌లోని బిల్లింగ్ చిరునామా విభాగం కోసం కంపెనీ పేరు ఫీల్డ్ కోసం దృశ్యమానతను మార్చండి.','Theme Bookshelf' => 'థీమ్ బుక్షెల్ఫ్','Output the checkout steps section from the Bookshelf theme when using Fluid Checkout.' => 'ఫ్లూయిడ్ చెక్అవుట్ ఉపయోగిస్తున్నప్పుడు బుక్షెల్ఫ్ థీమ్ నుండి చెక్అవుట్ స్టెప్స్ విభాగాన్ని అవుట్‌పుట్ చేయండి.','Account password' => 'ఖాతా పాస్‌వర్డ్','An account will be created with the information provided at checkout when completing the order.' => 'ఆర్డర్ పూర్తి చేసేటప్పుడు చెక్అవుట్ వద్ద అందించిన సమాచారంతో ఒక ఖాతా సృష్టించబడుతుంది.','Choose the style of the progress bar.' => 'ప్రోగ్రెస్ బార్ యొక్క శైలిని ఎంచుకోండి.','Bars' => 'బార్లు','Theme Ireca' => 'థీమ్ ఇరేకా','WooCommerce page layout' => 'WooCommerce పేజీ లేఅవుట్','Force wide layout on WooCommerce pages' => 'WooCommerce పేజీలలో ఫోర్స్ వైడ్ లేఅవుట్','This ensures the content section is not too narrow on WooCommerce pages including checkout, cart, order received, order pay and account pages.' => 'ఇది WooCommerce పేజీలలో చెక్అవుట్, కార్ట్, ఆర్డర్ రిసీవ్డ్, ఆర్డర్ పే మరియు అకౌంట్ పేజీలతో సహా కంటెంట్ విభాగం చాలా ఇరుకైనది కాదని నిర్ధారిస్తుంది.','WooCommerce Smart Coupons' => 'WooCommerce స్మార్ట్ కూపన్లు','Position on checkout page' => 'చెక్అవుట్ పేజీలో స్థానం','Choose where to display the available coupons section on the checkout page.' => 'చెక్అవుట్ పేజీలో అందుబాటులో ఉన్న కూపన్ల విభాగాన్ని ఎక్కడ ప్రదర్శించాలో ఎంచుకోండి.','Before the progress bar' => 'ప్రోగ్రెస్ బార్ ముందు','After the progress bar' => 'ప్రోగ్రెస్ బార్ తర్వాత','Before coupon codes section' => 'కూపన్ కోడ్‌ల విభాగానికి ముందు','Format phone numbers according to the rules for each country.' => 'ప్రతి దేశ నియమాల ప్రకారం ఫోన్ నంబర్‌లను ఫార్మాట్ చేయండి.','Use precise phone number validation' => 'ఖచ్చితమైన ఫోన్ నంబర్ వాలిడేషన్‌ను ఉపయోగించండి','This is an experimental feature and may not work as expected in all setups. Use it with caution.' => 'ఇది ఒక ప్రయోగాత్మక ఫీచర్ మరియు అన్ని సెటప్‌లలో ఆశించిన విధంగా పని చేయకపోవచ్చు. దీన్ని జాగ్రత్తగా ఉపయోగించండి.','Phone number validation types used when precise validation is enabled.' => 'ఖచ్చితమైన ధ్రువీకరణ ప్రారంభించబడినప్పుడు ఉపయోగించే ఫోన్ నంబర్ ధ్రువీకరణ రకాలు.','Mobile' => 'మొబైల్','Fixed line' => 'స్థిర లైన్','Toll free' => 'టోల్ ఫ్రీ','Or' => 'లేదా','Contact' => 'సంప్రదించండి','Multi step' => 'బహుళ దశలు','2 columns' => '2 నిలువు వరుసలు','1 column' => '1 నిలువు వరుస','Before checkout steps' => 'చెక్అవుట్ దశలకు ముందు','When using the <em>"1 column"</em> checkout layout this option is always set to <em>"Before checkout steps"</em> and also applies to desktop view.' => '<em>&quot;1 నిలువు వరుస&quot;</em> చెక్అవుట్ లేఅవుట్‌ను ఉపయోగిస్తున్నప్పుడు ఈ ఎంపిక ఎల్లప్పుడూ <em>&quot;చెక్అవుట్ దశలకు ముందు&quot;</em> కి సెట్ చేయబడుతుంది మరియు డెస్క్‌టాప్ వీక్షణకు కూడా వర్తిస్తుంది.','Position for the extra order summary section on mobile.' => 'మొబైల్‌లో అదనపు ఆర్డర్ సారాంశం విభాగం కోసం స్థానం.','The option <em>"On the site header"</em> only applies when using the distraction-free header.' => '<em>&quot;సైట్ హెడర్‌లో&quot;</em> అనే ఎంపిక డిస్ట్రాక్షన్-ఫ్రీ హెడర్‌ను ఉపయోగిస్తున్నప్పుడు మాత్రమే వర్తిస్తుంది.','On the site header (requires distraction-free header)' => 'సైట్ హెడర్‌లో (అంతరాయం లేని హెడర్ అవసరం)','Initial state for the expansible order summary section on mobile.' => 'మొబైల్‌లో విస్తరించదగిన ఆర్డర్ సారాంశం విభాగం యొక్క ప్రారంభ స్థితి.','We recommend setting it as <em>expanded</em> for the following countries due to regulatory requirements: <strong>Germany</strong>, <strong>Austria</strong>, <strong>Switzerland</strong>, <strong>Netherlands</strong>, <strong>Poland</strong>, <strong>Belgium</strong> and <strong>France</strong>.' => 'నియంత్రణ అవసరాల కారణంగా కింది దేశాలకు దీనిని <em>విస్తరించినట్లు</em> సెట్ చేయాలని మేము సిఫార్సు చేస్తున్నాము: <strong>జర్మనీ</strong> , <strong>ఆస్ట్రియా</strong> , <strong>స్విట్జర్లాండ్</strong> , <strong>నెదర్లాండ్స్</strong> , <strong>పోలాండ్</strong> , <strong>బెల్జియం</strong> మరియు <strong>ఫ్రాన్స్</strong> .','Collapsed' => 'కుదించబడింది','Expanded' => 'విస్తరించబడింది','Do not show' => 'చూపించవద్దు','yes' => 'అవును','The shipping phone field may be forced as "required" if the billing address section is displayed after the shipping address section, and the billing phone field is set as "required". This is needed to ensure the shipping address can be copied to the billing address when that option is checked, otherwise the customer might not be able to complete the checkout form.' => 'షిప్పింగ్ చిరునామా విభాగం తర్వాత బిల్లింగ్ చిరునామా విభాగం ప్రదర్శించబడి, బిల్లింగ్ ఫోన్ ఫీల్డ్ &#39;అవసరం&#39;గా సెట్ చేయబడితే, షిప్పింగ్ ఫోన్ ఫీల్డ్‌ను కూడా &#39;అవసరం&#39;గా బలవంతంగా మార్చవచ్చు. ఆ ఎంపికను ఎంచుకున్నప్పుడు షిప్పింగ్ చిరునామాను బిల్లింగ్ చిరునామాకు కాపీ చేయగలరని నిర్ధారించుకోవడానికి ఇది అవసరం, లేకపోతే కస్టమర్ చెక్అవుట్ ఫారమ్‌ను పూర్తి చేయలేకపోవచ్చు.','The billing phone field may be forced as "required" if the billing address section is displayed before the shipping address section, and the shipping phone field is set as "required". This is needed to ensure the shipping address can be copied to the billing address when that option is checked, otherwise the customer might not be able to complete the checkout form.' => 'షిప్పింగ్ చిరునామా విభాగానికి ముందు బిల్లింగ్ చిరునామా విభాగం ప్రదర్శించబడి, షిప్పింగ్ ఫోన్ ఫీల్డ్ కూడా &quot;అవసరం&quot;గా సెట్ చేయబడితే, బిల్లింగ్ ఫోన్ ఫీల్డ్‌ను కూడా &quot;అవసరం&quot;గా బలవంతంగా మార్చవచ్చు. ఆ ఎంపికను ఎంచుకున్నప్పుడు షిప్పింగ్ చిరునామాను బిల్లింగ్ చిరునామాకు కాపీ చేయగలరని నిర్ధారించుకోవడానికి ఇది అవసరం, లేకపోతే కస్టమర్ చెక్అవుట్ ఫారమ్‌ను పూర్తి చేయలేకపోవచ్చు.','Settings profiles' => 'సెట్టింగ్స్ ప్రొఫైల్స్','Settings profile' => 'సెట్టింగ్స్ ప్రొఫైల్','You do not have permission to perform this action.' => 'ఈ చర్యను నిర్వహించడానికి మీకు అనుమతి లేదు.','You do not have permission to activate plugins.' => 'మీకు ప్లగిన్‌లను యాక్టివేట్ చేయడానికి అనుమతి లేదు.','Missing plugin.' => 'ప్లగిన్ లేదు.','Plugin activated.' => 'ప్లగిన్ యాక్టివేట్ చేయబడింది.','The following changes will be applied:' => 'కింది మార్పులు వర్తింపజేయబడతాయి:','Since Fluid Checkout 5.0, settings are saved differently. Legacy options are still stored in the database to allow downgrades to previous versions if needed.' => 'ఫ్లూయిడ్ చెక్అవుట్ 5.0 నుండి, సెట్టింగ్‌లు వేరే విధంగా సేవ్ చేయబడతాయి. అవసరమైతే మునుపటి వెర్షన్‌లకు డౌన్‌గ్రేడ్ చేయడానికి వీలుగా పాత ఆప్షన్‌లు ఇప్పటికీ డేటాబేస్‌లో నిల్వ చేయబడతాయి.','Your store has been running for about 2 weeks on the new settings so you could clean up legacy options stored in the database. Please note that after cleanup, if you need to downgrade to previous versions of the plugin it will use default values for all settings.' => 'మీ స్టోర్ సుమారు 2 వారాలుగా కొత్త సెట్టింగ్‌లతో నడుస్తోంది, కాబట్టి మీరు డేటాబేస్‌లో నిల్వ చేయబడిన పాత ఆప్షన్‌లను శుభ్రపరచడం జరిగింది. దయచేసి గమనించండి, శుభ్రపరిచిన తర్వాత, మీరు ప్లగిన్ యొక్క మునుపటి వెర్షన్‌లకు డౌన్‌గ్రేడ్ చేయవలసి వస్తే, అది అన్ని సెట్టింగ్‌ల కోసం డిఫాల్ట్ విలువలను ఉపయోగిస్తుంది.','Fluid Checkout settings cleanup' => 'ఫ్లూయిడ్ చెక్అవుట్ సెట్టింగ్‌ల శుభ్రపరచడం','Delete leftover options' => 'మిగిలిపోయిన ఎంపికలను తొలగించండి','Help us improve Fluid Checkout' => 'ఫ్లూయిడ్ చెక్అవుట్‌ను మెరుగుపరచడంలో మాకు సహాయపడండి','Share anonymous site environment reports with Fluid Checkout to get faster support and help us improve compatibility and measure impact. No customer, user, or sensitive data are included. You can choose what is shared anytime from the Tools settings.' => 'వేగవంతమైన మద్దతును పొందడానికి, అనుకూలతను మెరుగుపరచడంలో మరియు ప్రభావాన్ని కొలవడంలో మాకు సహాయపడటానికి, ఫ్లూయిడ్ చెకౌట్‌తో అనామక సైట్ ఎన్విరాన్‌మెంట్ నివేదికలను పంచుకోండి. ఇందులో కస్టమర్, వినియోగదారు లేదా సున్నితమైన డేటా ఏదీ చేర్చబడదు. టూల్స్ సెట్టింగ్‌ల నుండి ఎప్పుడైనా ఏమి పంచుకోవాలో మీరు ఎంచుకోవచ్చు.','Enable site environment reports' => 'సైట్ పర్యావరణ నివేదికలను ప్రారంభించండి','Review settings' => 'సమీక్ష సెట్టింగ్‌లు','This preview has expired. Reload the admin page to start a new preview.' => 'ఈ ప్రివ్యూ గడువు ముగిసింది. కొత్త ప్రివ్యూను ప్రారంభించడానికి అడ్మిన్ పేజీని రీలోడ్ చేయండి.','Preview expired' => 'ప్రివ్యూ గడువు ముగిసింది','Orders cannot be placed in the preview.' => 'ప్రివ్యూలో ఆర్డర్‌లు ఇవ్వడం కుదరదు.','Logging in is not available in the preview.' => 'ప్రివ్యూలో లాగిన్ చేసే సౌకర్యం అందుబాటులో లేదు.','Accounts cannot be created in the preview.' => 'ప్రివ్యూలో ఖాతాలను సృష్టించడం సాధ్యపడదు.','Requests to other sites are blocked in the preview.' => 'ప్రివ్యూలో ఇతర సైట్‌లకు చేసే అభ్యర్థనలు నిరోధించబడతాయి.','Processing…' => 'ప్రాసెస్ అవుతోంది…','Something went wrong. Please try again.' => 'ఏదో పొరపాటు జరిగింది. దయచేసి మళ్ళీ ప్రయత్నించండి.','Activate plugin' => 'ప్లగిన్‌ను యాక్టివేట్ చేయండి','Fluid Checkout PRO - The complete checkout package' => 'ఫ్లూయిడ్ చెక్అవుట్ ప్రో - పూర్తి చెక్అవుట్ ప్యాకేజీ','All PRO features + all add-ons, one price. Design templates, optimized cart and order received pages, account matching, and much more.' => 'అన్ని ప్రో ఫీచర్లు + అన్ని యాడ్-ఆన్‌లు, ఒకే ధర. డిజైన్ టెంప్లేట్లు, ఆప్టిమైజ్ చేయబడిన కార్ట్ మరియు ఆర్డర్ స్వీకరించిన పేజీలు, అకౌంట్ మ్యాచింగ్, మరియు మరెన్నో.','Optimized order pay page' => 'ఆప్టిమైజ్ చేయబడిన ఆర్డర్ చెల్లింపు పేజీ','Express checkout buttons from supported payment methods' => 'మద్దతు ఉన్న చెల్లింపు పద్ధతుల నుండి ఎక్స్‌ప్రెస్ చెక్అవుట్ బటన్లు','Delayed account creation' => 'ఖాతా సృష్టిలో ఆలస్యం','Address autocomplete with Google Maps APIs' => 'Google Maps APIలతో చిరునామా ఆటోకంప్లీట్','Multiple saved addresses with the address book' => 'చిరునామా పుస్తకంలో బహుళ చిరునామాలు సేవ్ చేయబడ్డాయి','EU-VAT assistant' => 'EU-VAT సహాయకుడు','Hide this section' => 'ఈ విభాగాన్ని దాచండి','Learn more' => 'మరింత తెలుసుకోండి','Get early access' => 'ముందస్తు యాక్సెస్ పొందండి','Activate add-on' => 'యాడ్-ఆన్‌ను యాక్టివేట్ చేయండి','Get more out of your checkout journey' => 'మీ చెక్అవుట్ ప్రయాణం నుండి మరింత ప్రయోజనం పొందండి','Test API key' => 'టెస్ట్ API కీ','Guided setup' => 'గైడెడ్ సెటప్','Options' => 'ఎంపికలు','Set up layout and design on the <a href="%s">checkout options</a>.' => '<a href="%s">చెక్అవుట్ ఎంపికలలో</a> లేఅవుట్ మరియు డిజైన్‌ను సెట్ చేయండి.','Enable guest checkout and/or review <a href="%s">customer accounts settings</a>.' => 'అతిథి చెక్అవుట్‌ను ప్రారంభించండి మరియు/లేదా <a href="%s">కస్టమర్ ఖాతాల సెట్టింగ్‌లను</a> సమీక్షించండి.','Enable optimized <a href="%1$s">cart</a>, <a href="%2$s">thank you</a> and <a href="%3$s">order pay</a> pages.' => 'ఆప్టిమైజ్డ్ <a href="%1$s">కార్ట్</a> , <a href="%2$s">థ్యాంక్యూ</a> మరియు <a href="%3$s">ఆర్డర్ పే</a> పేజీలను ఎనేబుల్ చేయండి.','Enable <a href="%s">address autocomplete</a> from Google Maps.' => 'గూగుల్ మ్యాప్స్ నుండి <a href="%s">చిరునామా ఆటోకంప్లీట్‌ను</a> ఎనేబుల్ చేయండి.','Enable multiple saved addresses with <a href="%s">address book</a>.' => '<a href="%s">అడ్రస్ బుక్‌తో</a> బహుళ సేవ్ చేసిన చిరునామాలను ఎనేబుల్ చేయండి.','Check if there are any <a href="%s">integration options</a> available for the theme or other plugins you have installed.' => 'మీరు ఇన్‌స్టాల్ చేసిన థీమ్ లేదా ఇతర ప్లగిన్‌ల కోసం ఏవైనా <a href="%s">ఇంటిగ్రేషన్ ఆప్షన్‌లు</a> అందుబాటులో ఉన్నాయో లేదో తనిఖీ చేయండి.','Get faster support and help us improve compatibility and measure impact. <a href="%s">Enable usage tracking</a> from the tools settings.' => 'వేగవంతమైన మద్దతును పొందండి మరియు అనుకూలతను మెరుగుపరచడానికి, ప్రభావాన్ని కొలవడానికి మాకు సహాయపడండి. టూల్స్ సెట్టింగ్‌ల నుండి <a href="%s">వినియోగ ట్రాకింగ్‌ను ప్రారంభించండి</a> .','Missing settings tab.' => 'సెట్టింగ్స్ ట్యాబ్ కనిపించడం లేదు.','Getting started' => 'ప్రారంభించడం','<strong>Great! Your checkout page is now running on Fluid Checkout.</strong> Here are a few steps to get started:' => '<strong>చాలా బాగుంది! మీ చెక్అవుట్ పేజీ ఇప్పుడు ఫ్లూయిడ్ చెక్అవుట్‌లో నడుస్తోంది.</strong> ప్రారంభించడానికి ఇక్కడ కొన్ని దశలు ఉన్నాయి:','Completed' => 'పూర్తయింది','Preview report data' => 'నివేదిక డేటాను ప్రివ్యూ చేయండి','Send now' => 'ఇప్పుడే పంపండి','Auto-detect' => 'స్వయంచాలక గుర్తింపు','Afrikaans' => 'ఆఫ్రికాన్స్','Albanian' => 'అల్బేనియన్','Amharic' => 'అమ్హారిక్','Arabic' => 'అరబిక్','Armenian' => 'అర్మేనియన్','Azerbaijani' => 'అజర్‌బైజానీ','Basque' => 'బాస్క్','Belarusian' => 'బెలారసియన్','Bengali' => 'బెంగాలీ','Bosnian' => 'బోస్నియన్','Bulgarian' => 'బల్గేరియన్','Burmese' => 'బర్మీస్','Catalan' => 'కాటలాన్','Chinese' => 'చైనీస్','Chinese (Simplified)' => 'చైనీస్ (సరళీకృత)','Chinese (Hong Kong)' => 'చైనీస్ (హాంకాంగ్)','Chinese (Traditional)' => 'చైనీస్ (సాంప్రదాయ)','Croatian' => 'క్రొయేషియన్','Czech' => 'చెక్','Danish' => 'డానిష్','Dutch' => 'డచ్','English' => 'ఇంగ్లీష్','English (Australian)' => 'ఇంగ్లీష్ (ఆస్ట్రేలియన్)','English (Great Britain)' => 'ఇంగ్లీష్ (గ్రేట్ బ్రిటన్)','Estonian' => 'ఎస్టోనియన్','Farsi' => 'ఫార్సీ','Finnish' => 'ఫిన్నిష్','Filipino' => 'ఫిలిపినో','French' => 'ఫ్రెంచ్','French (Canadian)' => 'ఫ్రెంచ్ (కెనడియన్)','Galician' => 'గెలీషియన్','Georgian' => 'జార్జియన్','German' => 'జర్మన్','Greek' => 'గ్రీకు','Gujarati' => 'గుజరాతీ','Hebrew' => 'హీబ్రూ','Hindi' => 'హిందీ','Hungarian' => 'హంగేరియన్','Icelandic' => 'ఐస్లాండిక్','Indonesian' => 'ఇండోనేషియన్','Italian' => 'ఇటాలియన్','Japanese' => 'జపనీస్','Kannada' => 'కన్నడ','Kazakh' => 'కజఖ్','Khmer' => 'ఖ్మేర్','Korean' => 'కొరియన్','Kyrgyz' => 'కిర్గిజ్','Lao' => 'లావో','Latvian' => 'లాట్వియన్','Lithuanian' => 'లిథువేనియన్','Macedonian' => 'మాసిడోనియన్','Malay' => 'మలయ్','Malayalam' => 'మలయాళం','Marathi' => 'మరాఠీ','Mongolian' => 'మంగోలియన్','Nepali' => 'నేపాలీ','Norwegian' => 'నార్వేజియన్','Polish' => 'పోలిష్','Portuguese' => 'పోర్చుగీస్','Portuguese (Brazil)' => 'పోర్చుగీస్ (బ్రెజిల్)','Portuguese (Portugal)' => 'పోర్చుగీస్ (పోర్చుగల్)','Punjabi' => 'పంజాబీ','Romanian' => 'రొమేనియన్','Russian' => 'రష్యన్','Serbian' => 'సెర్బియన్','Sinhalese' => 'సింహళం','Slovak' => 'స్లోవాక్','Slovenian' => 'స్లోవేనియన్','Spanish' => 'స్పానిష్','Spanish (Latin America)' => 'స్పానిష్ (లాటిన్ అమెరికా)','Swahili' => 'స్వాహిలి','Swedish' => 'స్వీడిష్','Tamil' => 'తమిళం','Telugu' => 'తెలుగు','Thai' => 'థాయ్','Turkish' => 'టర్కిష్','Ukrainian' => 'ఉక్రేనియన్','Urdu' => 'ఉర్దూ','Vietnamese' => 'వియత్నామీస్','Zulu' => 'జులు','Google address autocomplete' => 'గూగుల్ చిరునామా ఆటోకంప్లీట్','Google Places API version' => 'గూగుల్ ప్లేసెస్ API వెర్షన్','Choose which version of the Google Places API to use. We recommend moving to the new Places API as soon as possible.' => 'Google Places API యొక్క ఏ వెర్షన్‌ను ఉపయోగించాలో ఎంచుకోండి. వీలైనంత త్వరగా కొత్త Places APIకి మారాలని మేము సిఫార్సు చేస్తున్నాము.','We recommend using "Places API (New)" as effective March 1, 2025, Google will move the "Places API (Legacy)" version into Legacy status, meaning you will no longer be able to enable this service for new API keys and that that version of the API will eventually not be available anymore. Existing accounts already using the Legacy API may continue to work without disruptions.' => 'మేము &quot;ప్లేసెస్ API (కొత్త)&quot;ని ఉపయోగించమని సిఫార్సు చేస్తున్నాము, ఎందుకంటే మార్చి 1, 2025 నుండి, Google &quot;ప్లేసెస్ API (లెగసీ)&quot; వెర్షన్‌ను లెగసీ స్థితిలోకి మార్చనుంది, అంటే మీరు ఇకపై కొత్త API కీల కోసం ఈ సేవను ఎనేబుల్ చేయలేరు మరియు ఆ API వెర్షన్ చివరికి అందుబాటులో ఉండదు. ఇప్పటికే లెగసీ APIని ఉపయోగిస్తున్న ప్రస్తుత ఖాతాలు ఎటువంటి అంతరాయాలు లేకుండా పని చేయడం కొనసాగించవచ్చు.','(Recommended)' => '(సిఫార్సు చేయబడింది)','Google API key' => 'గూగుల్ API కీ','Paste your Google API key and use the test button to confirm it works for this website. Make sure the key is valid and allowed for your domain, otherwise the address field might get blocked preventing customers from completing their orders.' => 'మీ Google API కీని అతికించి, అది ఈ వెబ్‌సైట్‌లో పనిచేస్తుందో లేదో నిర్ధారించుకోవడానికి టెస్ట్ బటన్‌ను ఉపయోగించండి. ఆ కీ చెల్లుబాటు అయ్యేదిగా మరియు మీ డొమైన్‌కు అనుమతించబడినదిగా ఉండేలా చూసుకోండి, లేకపోతే అడ్రస్ ఫీల్డ్ బ్లాక్ అయి, కస్టమర్‌లు తమ ఆర్డర్‌లను పూర్తి చేయకుండా నిరోధించబడవచ్చు.','Enable Google address autocomplete' => 'Google చిరునామా ఆటోకంప్లీట్‌ను ప్రారంభించండి','Enable address autocompletion using the Google Maps APIs.' => 'Google Maps APIలను ఉపయోగించి చిరునామా ఆటోకంప్లీషన్‌ను ప్రారంభించండి.','Google API language' => 'గూగుల్ API భాష','This language will be used to display the Google Places API address suggestions and addresses will also be autocompleted in this language.' => 'Google Places API చిరునామా సూచనలను ప్రదర్శించడానికి ఈ భాషను ఉపయోగిస్తారు మరియు చిరునామాలు కూడా ఈ భాషలోనే స్వయంచాలకంగా పూర్తి చేయబడతాయి.','Result types' => 'ఫలిత రకాలు','Leave empty to accept any type of results, which usually yields better matching results. <a href="%s" target="_blank">See documentation for more details</a>. <br>Select up to 5 types of address search results to return on address autocomplete fields. <br>Visit the Google Maps documentation to learn more about the <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">supported types</a>.' => 'ఏ రకమైన ఫలితాలనైనా అంగీకరించడానికి ఖాళీగా వదిలేయండి, దీనివల్ల సాధారణంగా మెరుగైన సరిపోలిక ఫలితాలు వస్తాయి. <a href="%s" target="_blank">మరిన్ని వివరాల కోసం డాక్యుమెంటేషన్ చూడండి</a> .<br> చిరునామా ఆటోకంప్లీట్ ఫీల్డ్‌లలో తిరిగి పొందడానికి 5 రకాల చిరునామా శోధన ఫలితాల వరకు ఎంచుకోండి.<br> <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">మద్దతు ఉన్న రకాల</a> గురించి మరింత తెలుసుకోవడానికి Google Maps డాక్యుమెంటేషన్‌ను సందర్శించండి.','Result types (Legacy API)' => 'ఫలిత రకాలు (లెగసీ API)','Which type of address search results to return when using Places API (Legacy). <br>Visit the documentation of the Legacy Google Places API to learn more about the <a href="https://developers.google.com/maps/documentation/places/web-service/supported_types#table3" target="_blank">supported types</a>.' => 'Places API (Legacy)ని ఉపయోగిస్తున్నప్పుడు ఏ రకమైన చిరునామా శోధన ఫలితాలను తిరిగి ఇవ్వాలి.<br> <a href="https://developers.google.com/maps/documentation/places/web-service/supported_types#table3" target="_blank">మద్దతు ఉన్న రకాల</a> గురించి మరింత తెలుసుకోవడానికి లెగసీ గూగుల్ ప్లేసెస్ API డాక్యుమెంటేషన్‌ను సందర్శించండి.','Company fields' => 'కంపెనీ ఫీల్డ్‌లు','Enable autocomplete for the company name if available' => 'అందుబాటులో ఉంటే కంపెనీ పేరు కోసం ఆటోకంప్లీట్‌ను ఎనేబుల్ చేయండి','Enable autocompletion of the company field with the company name information when returned from the Google Maps APIs.' => 'Google Maps APIల నుండి తిరిగి వచ్చినప్పుడు, కంపెనీ పేరు సమాచారంతో కంపెనీ ఫీల్డ్‌ను ఆటోకంప్లీషన్ చేయడానికి ఎనేబుల్ చేయండి.','Business search' => 'వ్యాపార శోధన','Enable search for businesses in the company field' => 'కంపెనీ రంగంలో వ్యాపారాల కోసం శోధనను ప్రారంభించండి','Enable suggestion of addresses associated with a business when typing in the company field, then autocomplete all addresses fields when a business is selected from the suggestions.' => 'కంపెనీ ఫీల్డ్‌లో టైప్ చేస్తున్నప్పుడు వ్యాపారానికి సంబంధించిన చిరునామాల సూచనను ఎనేబుల్ చేయండి, ఆపై సూచనల నుండి వ్యాపారాన్ని ఎంచుకున్నప్పుడు అన్ని చిరునామాల ఫీల్డ్‌లను ఆటోకంప్లీట్ చేయండి.','Company result types' => 'కంపెనీ ఫలిత రకాలు','Select up to 5 types of address search results to return on autocomplete company fields. <br>Recommended value is <code>establishment</code>, which includes most types of businesses. <br>Leave empty to accept any type of results, including results that are not related to businesses. <br>Visit the Google Maps documentation to learn more about the <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">supported types</a>.' => 'ఆటోకంప్లీట్ కంపెనీ ఫీల్డ్‌లలో తిరిగి పొందడానికి 5 రకాల చిరునామా శోధన ఫలితాల వరకు ఎంచుకోండి.<br> సిఫార్సు చేయబడిన విలువ <code>establishment</code> , ఇందులో చాలా రకాల వ్యాపారాలు ఉంటాయి.<br> వ్యాపారాలకు సంబంధం లేని ఫలితాలతో సహా, ఏ రకమైన ఫలితాలనైనా అంగీకరించడానికి ఖాళీగా వదిలేయండి.<br> <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">మద్దతు ఉన్న రకాల</a> గురించి మరింత తెలుసుకోవడానికి Google Maps డాక్యుమెంటేషన్‌ను సందర్శించండి.','Google logo' => 'గూగుల్ లోగో','Show text and logo "Powered by Google"' => 'టెక్స్ట్ మరియు లోగోను చూపించు &quot;Google ద్వారా ఆధారితం&quot;','When checked, the text and logo "Powered by Google" will be displayed at the bottom of the address autocomplete suggestions box.' => 'ఎంచుకున్నప్పుడు, చిరునామా ఆటోకంప్లీట్ సూచనల పెట్టె దిగువన &quot;Powered by Google&quot; అనే టెక్స్ట్ మరియు లోగో ప్రదర్శించబడుతుంది.','Brasil API address autocomplete' => 'బ్రెజిల్ API చిరునామా ఆటోకంప్లీట్','Brasil API' => 'బ్రెజిల్ API','Enable Brasil API address autocomplete for CEP fields' => 'CEP ఫీల్డ్‌ల కోసం బ్రెజిల్ API చిరునామా ఆటోకంప్లీట్‌ను ప్రారంభించండి','Use Brasil API to retrieve and autofill addresses using the CEP/Postcode field. Only relevant for Brazilian addresses.' => 'CEP/పోస్ట్‌కోడ్ ఫీల్డ్‌ను ఉపయోగించి చిరునామాలను తిరిగి పొందడానికి మరియు ఆటోఫిల్ చేయడానికి బ్రెజిల్ APIని ఉపయోగించండి. ఇది బ్రెజిలియన్ చిరునామాలకు మాత్రమే వర్తిస్తుంది.','API version' => 'API వెర్షన్','Choose which version of the Brasil API CEP method to use.' => 'బ్రెజిల్ API CEP పద్ధతి యొక్క ఏ వెర్షన్‌ను ఉపయోగించాలో ఎంచుకోండి.','Address book migration' => 'చిరునామా పుస్తక వలస','WooCommerce addresses' => 'WooCommerce చిరునామాలు','Copy existing shipping and billing addresses from WooCommerce into the customers\' address book.' => 'WooCommerce నుండి ఇప్పటికే ఉన్న షిప్పింగ్ మరియు బిల్లింగ్ చిరునామాలను కస్టమర్ల అడ్రస్ బుక్‌లోకి కాపీ చేయండి.','Enable the address book feature' => 'చిరునామా పుస్తకం ఫీచర్‌ను ప్రారంభించండి','Allow customers to save multiple addresses and define the default address to be used for shipping and billing.' => 'వినియోగదారులు బహుళ చిరునామాలను సేవ్ చేసుకోవడానికి మరియు షిప్పింగ్, బిల్లింగ్ కోసం ఉపయోగించాల్సిన డిఫాల్ట్ చిరునామాను నిర్వచించడానికి అనుమతించండి.','Address labels' => 'చిరునామా లేబుల్‌లు','Allow customers to add a custom label for each address' => 'ప్రతి చిరునామాకు కస్టమ్ లేబుల్‌ను జోడించడానికి కస్టమర్లను అనుమతించండి','Address labels make it easier to for customers to distinguish between their saved addresses (ie.: "Mom\'s House"). The address labels are private to the customers, and will not be displayed or printed on the order details page or invoices.' => 'చిరునామా లేబుల్‌లు, కస్టమర్‌లు తాము సేవ్ చేసుకున్న చిరునామాలను (ఉదా: &quot;అమ్మగారి ఇల్లు&quot;) సులభంగా గుర్తించడానికి వీలు కల్పిస్తాయి. ఈ చిరునామా లేబుల్‌లు కస్టమర్‌లకు మాత్రమే ప్రత్యేకమైనవి, మరియు అవి ఆర్డర్ వివరాల పేజీలో గానీ లేదా ఇన్‌వాయిస్‌లలో గానీ ప్రదర్శించబడవు లేదా ముద్రించబడవు.','Display layout' => 'ప్రదర్శన లేఅవుట్','Choose how saved addresses are displayed at checkout and on the cart.' => 'సేవ్ చేసిన చిరునామాలు చెక్అవుట్ వద్ద మరియు కార్ట్‌లో ఎలా ప్రదర్శించబడాలో ఎంచుకోండి.','Applies at checkout and on the cart. Saved addresses on the account page always use the cards layout.' => 'ఇది చెక్అవుట్ వద్ద మరియు కార్ట్‌లో వర్తిస్తుంది. ఖాతా పేజీలో సేవ్ చేయబడిన చిరునామాలు ఎల్లప్పుడూ కార్డ్ లేఅవుట్‌ను ఉపయోగిస్తాయి.','Address cards' => 'చిరునామా కార్డులు','Address list' => 'చిరునామా జాబితా','Dropdown field' => 'డ్రాప్‌డౌన్ ఫీల్డ్','Address search' => 'చిరునామా శోధన','Show address search filter on frontend when customer has at least this number of saved addresses available.' => 'కస్టమర్ వద్ద కనీసం ఈ సంఖ్యలో సేవ్ చేయబడిన చిరునామాలు అందుబాటులో ఉన్నప్పుడు ఫ్రంటెండ్‌లో చిరునామా శోధన ఫిల్టర్‌ను చూపించండి.','Not used when display layout is set to dropdown field.' => 'డిస్ప్లే లేఅవుట్‌ను డ్రాప్‌డౌన్ ఫీల్డ్‌గా సెట్ చేసినప్పుడు ఉపయోగించబడదు.','Addresses' => 'చిరునామాలు','Enable cart page optimizations to see more options' => 'మరిన్ని ఎంపికలను చూడటానికి కార్ట్ పేజీ ఆప్టిమైజేషన్‌లను ఎనేబుల్ చేయండి','Sticky order summary' => 'స్టిక్కీ ఆర్డర్ సారాంశం','Select position where to display the coupon codes section on the cart page. Only applicable when AJAX cart is enabled, and if use of coupon codes are enabled in the WooCommerce settings.' => 'కార్ట్ పేజీలో కూపన్ కోడ్‌ల విభాగాన్ని ప్రదర్శించాల్సిన స్థానాన్ని ఎంచుకోండి. AJAX కార్ట్ ఎనేబుల్ చేయబడి, మరియు WooCommerce సెట్టింగ్‌లలో కూపన్ కోడ్‌ల వాడకం ఎనేబుల్ చేయబడి ఉంటే మాత్రమే ఇది వర్తిస్తుంది.','Layout of cross-sell' => 'క్రాస్-సెల్ యొక్క లేఅవుట్','Cross-sells displayed' => 'ప్రదర్శించబడిన క్రాస్-సెల్స్','Items' => 'వస్తువులు','Cart page optimization' => 'కార్ట్ పేజీ ఆప్టిమైజేషన్','Give your cart the same clear, conversion-focused layout as your checkout.' => 'మీ చెక్అవుట్ మాదిరిగానే మీ కార్ట్‌కు కూడా స్పష్టమైన, అమ్మకాలను పెంచే లేఅవుట్‌ను ఇవ్వండి.','Match the cart layout to the checkout page for a consistent purchase journey.' => 'స్థిరమైన కొనుగోలు ప్రక్రియ కోసం కార్ట్ లేఅవుట్‌ను చెక్అవుట్ పేజీకి అనుగుణంగా మార్చండి.','Keep the cart always updated in the background, no full page reloads when quantities change.' => 'కార్ట్‌ను నేపథ్యంలో ఎల్లప్పుడూ అప్‌డేట్‌గా ఉంచండి, పరిమాణాలు మారినప్పుడు పూర్తి పేజీ రీలోడ్‌లు జరగవు.','Place coupon codes, shipping, and cross-sells exactly where they convert best.' => 'కూపన్ కోడ్‌లు, షిప్పింగ్ మరియు క్రాస్-సెల్‌లను అవి ఉత్తమంగా పనిచేసే చోటనే ఉంచండి.','Keep the order summary visible while scrolling, and add trust symbols where shoppers need reassurance.' => 'స్క్రోల్ చేస్తున్నప్పుడు ఆర్డర్ సారాంశం కనిపించేలా ఉంచండి మరియు కొనుగోలుదారులకు భరోసా అవసరమైన చోట నమ్మకపు చిహ్నాలను జోడించండి.','Columns' => 'కాలమ్స్','General styles for the checkout steps, order summary and other sections. Applies to other checkout, cart, thank you (order received), and view order pages.' => 'చెక్అవుట్ దశలు, ఆర్డర్ సారాంశం మరియు ఇతర విభాగాల కోసం సాధారణ శైలులు. ఇతర చెక్అవుట్, కార్ట్, ధన్యవాదాలు (ఆర్డర్ స్వీకరించబడింది), మరియు ఆర్డర్ వీక్షణ పేజీలకు వర్తిస్తుంది.','When using the <em>"1 column"</em> layout with the <em>"Split"</em> design template, a right column is shown only if the page sidebar widget area is active (Checkout Sidebar, Cart Sidebar, or Order Received Sidebar). Otherwise the page stays as a single column with Split styles.' => '<em>&quot;స్ప్లిట్&quot;</em> డిజైన్ టెంప్లేట్‌తో <em>&quot;1 కాలమ్&quot;</em> లేఅవుట్‌ను ఉపయోగిస్తున్నప్పుడు, పేజీ సైడ్‌బార్ విడ్జెట్ ఏరియా (చెక్అవుట్ సైడ్‌బార్, కార్ట్ సైడ్‌బార్ లేదా ఆర్డర్ రిసీవ్డ్ సైడ్‌బార్) యాక్టివ్‌గా ఉంటేనే కుడి కాలమ్ చూపబడుతుంది. లేకపోతే, స్ప్లిట్ స్టైల్స్‌తో పేజీ ఒకే కాలమ్‌గా ఉంటుంది.','Split column background' => 'విభజిత నిలువు వరుస నేపథ్యం','Choose a background color for the Split design secondary column. Leave empty to use the order summary background color.' => 'స్ప్లిట్ డిజైన్ సెకండరీ కాలమ్ కోసం బ్యాక్‌గ్రౌండ్ రంగును ఎంచుకోండి. ఆర్డర్ సారాంశం బ్యాక్‌గ్రౌండ్ రంగును ఉపయోగించడానికి దీనిని ఖాళీగా వదిలేయండి.','Page templates' => 'పేజీ టెంప్లేట్లు','Checkout template' => 'చెక్అవుట్ టెంప్లేట్','Recommended for fewer distractions at checkout. <a href="https://baymard.com/blog/cart-abandonment" target="_blank">Read the research about cart abandonment</a>.' => 'చెల్లింపు సమయంలో పరధ్యానాలను తగ్గించుకోవడానికి ఇది సిఫార్సు చేయబడింది. <a href="https://baymard.com/blog/cart-abandonment" target="_blank">కార్ట్ పరిత్యాగం గురించిన పరిశోధనను చదవండి</a> .','Sticky progress bar' => 'స్టిక్కీ ప్రోగ్రెస్ బార్','Progress bar style' => 'ప్రోగ్రెస్ బార్ శైలి','Order totals' => 'ఆర్డర్ మొత్తాలు','Background color' => 'నేపథ్య రంగు','Action link' => 'చర్య లింక్','Mobile order summary' => 'మొబైల్ ఆర్డర్ సారాంశం','Mobile initial state' => 'మొబైల్ ప్రారంభ స్థితి','Enable editing cart items at checkout' => 'చెక్అవుట్ వద్ద కార్ట్ ఐటెమ్‌లను సవరించడాన్ని ప్రారంభించండి','Allow customers to change product quantities or remove items directly at the checkout page.' => 'కస్టమర్‌లు చెక్అవుట్ పేజీలోనే నేరుగా ఉత్పత్తి పరిమాణాలను మార్చుకోవడానికి లేదా వస్తువులను తొలగించుకోవడానికి అనుమతించండి.','Cart item errors' => 'కార్ట్ ఐటమ్ లోపాలు','Only applicable when coupon code is displayed as a separate section on the checkout or cart pages, and if use of coupon codes are enabled in the WooCommerce settings.' => 'చెక్అవుట్ లేదా కార్ట్ పేజీలలో కూపన్ కోడ్ ఒక ప్రత్యేక విభాగంగా ప్రదర్శించబడినప్పుడు మరియు WooCommerce సెట్టింగ్‌లలో కూపన్ కోడ్‌ల వాడకం ఎనేబుల్ చేయబడినప్పుడు మాత్రమే ఇది వర్తిస్తుంది.','Coupon codes position' => 'కూపన్ కోడ్‌ల స్థానం','Apply coupon button' => 'కూపన్ బటన్‌ను వర్తింపజేయండి','Select style of the "apply coupon" button.' => '&quot;కూపన్‌ను వర్తింపజేయండి&quot; బటన్ యొక్క శైలిని ఎంచుకోండి.','Address line 2' => 'చిరునామా లైన్ 2','This setting is shared between the Checkout and Local pickup sections. On the Local pickup section, it also decides whether the Ship/Pickup selector shows inside the shipping method section (before the address) or as a separate section (after).' => 'ఈ సెట్టింగ్ చెక్అవుట్ మరియు లోకల్ పికప్ విభాగాలకు ఉమ్మడిగా వర్తిస్తుంది. లోకల్ పికప్ విభాగంలో, షిప్/పికప్ సెలెక్టర్ షిప్పింగ్ పద్ధతి విభాగంలో (చిరునామాకు ముందు) కనిపించాలా లేదా ఒక ప్రత్యేక విభాగంగా (తర్వాత) కనిపించాలా అని కూడా ఇది నిర్ణయిస్తుంది.','Customer accounts' => 'కస్టమర్ ఖాతాలు','Guest checkout' => 'అతిథి చెక్అవుట్','Guest checkout, login, and account creation options from the WooCommerce Accounts settings page. They are managed here for your convenience, and so you can use different values per settings profile.' => 'WooCommerce ఖాతాల సెట్టింగ్‌ల పేజీ నుండి అతిథి చెక్అవుట్, లాగిన్ మరియు ఖాతా సృష్టి ఎంపికలు. మీ సౌలభ్యం కోసం అవి ఇక్కడ నిర్వహించబడతాయి, కాబట్టి మీరు ప్రతి సెట్టింగ్‌ల ప్రొఫైల్‌కు వేర్వేరు విలువలను ఉపయోగించవచ్చు.','Allow customers to checkout without an account' => 'ఖాతా లేకుండా కస్టమర్‌లు చెక్అవుట్ చేయడానికి అనుమతించండి','<strong>Recommended</strong> so customers are not asked to create an account or log in during checkout, which can lower conversion rates.' => 'చెక్అవుట్ సమయంలో కస్టమర్లను ఖాతా సృష్టించమని లేదా లాగిన్ అవ్వమని అడగకుండా ఉండేందుకు <strong>ఇది సిఫార్సు చేయబడింది</strong> , దీనివల్ల కన్వర్షన్ రేట్లు తగ్గుతాయి.','When disabled, customers must log in or create an account to complete the purchase.' => 'ఇది నిలిపివేయబడినప్పుడు, కొనుగోలును పూర్తి చేయడానికి వినియోగదారులు లాగిన్ అవ్వాలి లేదా ఖాతాను సృష్టించుకోవాలి.','Login at checkout' => 'చెక్అవుట్ వద్ద లాగిన్ చేయండి','Enable log-in during checkout' => 'చెక్అవుట్ సమయంలో లాగిన్‌ను ప్రారంభించండి','Show a link for returning customers to log in from the checkout page.' => 'తిరిగి వచ్చే కస్టమర్‌లు చెక్అవుట్ పేజీ నుండి లాగిన్ అవ్వడానికి ఒక లింక్‌ను చూపించండి.','Account creation' => 'ఖాతా సృష్టి','Allow customers to create an account during checkout' => 'చెక్అవుట్ సమయంలో ఖాతాను సృష్టించుకోవడానికి వినియోగదారులను అనుమతించండి','Customers can create an account before placing their order.' => 'వినియోగదారులు తమ ఆర్డర్‌ను ఇచ్చే ముందు ఖాతాను సృష్టించుకోవచ్చు.','Allow customers to create an account from the My account page' => 'నా ఖాతా పేజీ నుండి ఖాతాను సృష్టించుకోవడానికి వినియోగదారులను అనుమతించండి','Customers can register a new account from the My account page.' => 'వినియోగదారులు &#39;నా ఖాతా&#39; పేజీ నుండి కొత్త ఖాతాను నమోదు చేసుకోవచ్చు.','Username' => 'వినియోగదారు పేరు','Generate from customer\'s name' => 'కస్టమర్ పేరు నుండి రూపొందించండి','<strong>Recommended</strong> so customers are not asked to choose a username during checkout, which can lower conversion rates.' => 'చెక్అవుట్ సమయంలో కస్టమర్లను యూజర్‌నేమ్ ఎంచుకోమని అడగకుండా ఉండేందుకు <strong>ఇది సిఫార్సు చేయబడింది</strong> , దీనివల్ల కన్వర్షన్ రేట్లు తగ్గే అవకాశం ఉంది.','A username is generated from the customer name, or from the email address when a name cannot be used.' => 'వినియోగదారుడి పేరు నుండి లేదా పేరును ఉపయోగించలేని పక్షంలో ఇమెయిల్ చిరునామా నుండి వినియోగదారు పేరు రూపొందించబడుతుంది.','Password' => 'పాస్‌వర్డ్','Send password setup link' => 'పాస్‌వర్డ్ సెటప్ లింక్‌ను పంపండి','<strong>Recommended</strong> so customers are not asked to set a password during checkout, which can lower conversion rates.' => 'చెక్అవుట్ సమయంలో కస్టమర్లను పాస్‌వర్డ్ సెట్ చేయమని అడగకుండా ఉండేందుకు <strong>ఇది సిఫార్సు చేయబడింది</strong> , దీనివల్ల కన్వర్షన్ రేట్లు తగ్గే అవకాశం ఉంది.','Customers receive an email to create their password securely.' => 'వినియోగదారులు తమ పాస్‌వర్డ్‌ను సురక్షితంగా సృష్టించుకోవడానికి ఒక ఇమెయిల్‌ను అందుకుంటారు.','Let registered customers complete checkout without logging in and associate the order with their existing account when contact details match.' => 'నమోదిత కస్టమర్‌లు లాగిన్ చేయకుండానే చెక్అవుట్ పూర్తి చేయడానికి మరియు సంప్రదింపు వివరాలు సరిపోలినప్పుడు ఆర్డర్‌ను వారి ప్రస్తుత ఖాతాతో అనుబంధించడానికి అనుమతించండి.','Existing account message' => 'ఇప్పటికే ఉన్న ఖాతా సందేశం','Let customers create an account after placing their order, from the thank you page.' => 'కస్టమర్‌లు తమ ఆర్డర్‌ను ఇచ్చిన తర్వాత, ధన్యవాదాల పేజీ నుండి ఖాతాను సృష్టించుకునేలా అనుమతించండి.','Options in this section are available when guest checkout and account matching are enabled. Enable both features above to configure delayed account creation.' => 'అతిథి చెక్అవుట్ మరియు ఖాతా సరిపోలిక ప్రారంభించబడినప్పుడు ఈ విభాగంలోని ఎంపికలు అందుబాటులో ఉంటాయి. ఆలస్యంగా ఖాతా సృష్టించడాన్ని కాన్ఫిగర్ చేయడానికి పైన పేర్కొన్న రెండు ఫీచర్‌లను ప్రారంభించండి.','Enable delayed account creation' => 'ఆలస్యమైన ఖాతా సృష్టిని ప్రారంభించండి','Enable delayed account creation when both guest checkout and account matching are enabled.' => 'అతిథి చెక్అవుట్ మరియు ఖాతా సరిపోలిక రెండూ ప్రారంభించబడినప్పుడు, ఖాతా సృష్టిని ఆలస్యం చేయడానికి అనుమతించండి.','Section position' => 'విభాగం స్థానం','Before customer details section' => 'కస్టమర్ వివరాల విభాగానికి ముందు','After customer details section' => 'కస్టమర్ వివరాల విభాగం తర్వాత','Account creation benefits' => 'ఖాతా సృష్టి ప్రయోజనాలు','Leaving the field empty will display the default text.' => 'ఫీల్డ్‌ను ఖాళీగా వదిలేస్తే డిఫాల్ట్ టెక్స్ట్ ప్రదర్శించబడుతుంది.','Inline buttons' => 'ఇన్‌లైన్ బటన్లు','Required fields' => 'అవసరమైన ఫీల్డ్‌లు','Enable gift message fields at checkout' => 'చెక్అవుట్ వద్ద బహుమతి సందేశ ఫీల్డ్‌లను ఎనేబుల్ చేయండి','Expanded gift message' => 'విస్తరించిన బహుమతి సందేశం','Display gift message field always expanded' => 'బహుమతి సందేశ ఫీల్డ్‌ను ఎల్లప్పుడూ విస్తరించి ప్రదర్శించండి','Gift message in order details' => 'ఆర్డర్ వివరాలలో బహుమతి సందేశం','No integrations available at the moment on this section. The options related to each plugin and theme will only appear here when that plugin or theme is activated.' => 'ప్రస్తుతానికి ఈ విభాగంలో ఎలాంటి ఇంటిగ్రేషన్‌లు అందుబాటులో లేవు. ప్రతి ప్లగిన్ లేదా థీమ్‌కు సంబంధించిన ఆప్షన్‌లు, ఆ ప్లగిన్ లేదా థీమ్ యాక్టివేట్ చేయబడినప్పుడు మాత్రమే ఇక్కడ కనిపిస్తాయి.','Phone fields' => 'ఫోన్ ఫీల్డ్‌లు','Field visibility' => 'క్షేత్ర దృశ్యమానత','Field position' => 'క్షేత్ర స్థానం','Phone country code & validation' => 'ఫోన్ దేశ కోడ్ మరియు ధృవీకరణ','Country' => 'దేశం','Enable country on phone fields' => 'ఫోన్ ఫీల్డ్‌లలో దేశాన్ని ఎనేబుల్ చేయండి','Filter countries for shipping or billing' => 'షిప్పింగ్ లేదా బిల్లింగ్ కోసం దేశాలను ఫిల్టర్ చేయండి','Limit the country selector on each phone field to the countries allowed for shipping or billing on your store.' => 'ప్రతి ఫోన్ ఫీల్డ్‌లోని దేశ ఎంపికను, మీ స్టోర్‌లో షిప్పింగ్ లేదా బిల్లింగ్ కోసం అనుమతించబడిన దేశాలకు మాత్రమే పరిమితం చేయండి.','Validation' => 'ధ్రువీకరణ','Enable simple validation based on country rules' => 'దేశ నియమాల ఆధారంగా సరళమైన ధ్రువీకరణను ప్రారంభించండి','Checks that the phone number is valid for the selected country, including country code and length.' => 'ఎంచుకున్న దేశానికి ఫోన్ నంబర్ చెల్లుబాటు అవుతుందో లేదో, దేశ కోడ్ మరియు పొడవుతో సహా తనిఖీ చేస్తుంది.','Stricter check that the number is a valid mobile, fixed line, or other accepted type for the selected country. May reject some valid numbers.' => 'ఎంచుకున్న దేశానికి ఆ నంబర్ చెల్లుబాటు అయ్యే మొబైల్, ఫిక్స్‌డ్ లైన్ లేదా ఇతర ఆమోదించబడిన రకానికి చెందినదో కాదో మరింత కఠినంగా తనిఖీ చేస్తుంది. కొన్ని చెల్లుబాటు అయ్యే నంబర్‌లను తిరస్కరించవచ్చు.','Validation types' => 'ధ్రువీకరణ రకాలు','Placeholders' => 'ప్లేస్‌హోల్డర్‌లు','No license keys to manage at the moment. License keys will appear here when a licensed Fluid Checkout plugin or add-on is active.' => 'ప్రస్తుతానికి నిర్వహించడానికి లైసెన్స్ కీలు ఏవీ లేవు. లైసెన్స్ పొందిన ఫ్లూయిడ్ చెక్అవుట్ ప్లగిన్ లేదా యాడ్-ఆన్ యాక్టివ్‌గా ఉన్నప్పుడు లైసెన్స్ కీలు ఇక్కడ కనిపిస్తాయి.','Default delivery type' => 'డిఫాల్ట్ డెలివరీ రకం','Choose which delivery type will be selected by default.' => 'డిఫాల్ట్‌గా ఏ డెలివరీ రకం ఎంపిక చేయబడాలో ఎంచుకోండి.','Shipping zone fields' => 'షిప్పింగ్ జోన్ ఫీల్డ్‌లు','Choose which fields will be displayed for the local pickup shipping zone filter fields. Leave empty to show all available options.' => 'స్థానిక పికప్ షిప్పింగ్ జోన్ ఫిల్టర్ ఫీల్డ్‌ల కోసం ఏ ఫీల్డ్‌లు ప్రదర్శించబడాలో ఎంచుకోండి. అందుబాటులో ఉన్న అన్ని ఎంపికలను చూపించడానికి ఖాళీగా వదిలేయండి.','These fields will be displayed as a filter for the local pickup shipping methods. Some fields might still appear at checkout when not selected here, if compatible plugins require them to work properly.' => 'ఈ ఫీల్డ్‌లు స్థానిక పికప్ షిప్పింగ్ పద్ధతుల కోసం ఫిల్టర్‌గా ప్రదర్శించబడతాయి. అనుకూలమైన ప్లగిన్‌లు సరిగ్గా పనిచేయడానికి కొన్ని ఫీల్డ్‌లు అవసరమైతే, ఇక్కడ ఎంచుకోనప్పటికీ అవి చెక్అవుట్ వద్ద కనిపించవచ్చు.','Order shipping address' => 'ఆర్డర్ షిప్పింగ్ చిరునామా','Order pay page optimization' => 'ఆర్డర్ చెల్లింపు పేజీ ఆప్టిమైజేషన్','Give unpaid orders the same clear, conversion-focused layout as checkout.' => 'చెల్లించని ఆర్డర్‌లకు కూడా చెక్అవుట్ మాదిరిగానే స్పష్టమైన, మార్పిడి-కేంద్రీకృత లేఅవుట్‌ను ఇవ్వండి.','Optimize the layout of the order pay page for orders pending payment.' => 'చెల్లింపు కోసం వేచి ఉన్న ఆర్డర్‌ల కోసం ఆర్డర్ చెల్లింపు పేజీ యొక్క లేఅవుట్‌ను ఆప్టిమైజ్ చేయండి.','Match the order pay experience to your checkout for a consistent purchase journey.' => 'స్థిరమైన కొనుగోలు ప్రయాణం కోసం, ఆర్డర్ చెల్లింపు అనుభవాన్ని మీ చెక్అవుట్‌కు అనుగుణంగా మార్చండి.','Add trust symbols and badges where shoppers need reassurance before paying.' => 'చెల్లించే ముందు కొనుగోలుదారులకు భరోసా అవసరమయ్యే చోట నమ్మకపు చిహ్నాలను మరియు బ్యాడ్జ్‌లను జోడించండి.','Thank you page optimization' => 'పేజీ ఆప్టిమైజేషన్‌కు ధన్యవాదాలు','Make the thank you page and order details clearer for customers after they buy.' => 'వినియోగదారులు కొనుగోలు చేసిన తర్వాత, వారికి ధన్యవాదాల పేజీని మరియు ఆర్డర్ వివరాలను మరింత స్పష్టంగా తెలియజేయండి.','Optimize the thank you page and account order details with a clearer layout.' => 'ధన్యవాదాల పేజీని మరియు ఖాతా ఆర్డర్ వివరాలను మరింత స్పష్టమైన లేఅవుట్‌తో మెరుగుపరచండి.','Show order status progress, actions, downloads, and notes where they make sense.' => 'అవసరమైన చోట ఆర్డర్ స్థితి పురోగతి, చర్యలు, డౌన్‌లోడ్‌లు మరియు గమనికలను చూపించండి.','Customize order details sections on email notifications.' => 'ఇమెయిల్ నోటిఫికేషన్‌లలో ఆర్డర్ వివరాల విభాగాలను అనుకూలీకరించండి.','Add trust symbols and badges where shoppers need reassurance after purchase.' => 'కొనుగోలు తర్వాత కొనుగోలుదారులకు భరోసా అవసరమయ్యే చోట నమ్మకపు చిహ్నాలను మరియు బ్యాడ్జ్‌లను జోడించండి.','Email notifications' => 'ఇమెయిల్ నోటిఫికేషన్లు','Enable thank you page and order details optimizations to see more options' => 'మరిన్ని ఎంపికలను చూడటానికి ధన్యవాదాల పేజీ మరియు ఆర్డర్ వివరాల ఆప్టిమైజేషన్‌లను ఎనేబుల్ చేయండి','Use wide layout on thank you page' => 'ధన్యవాదాల పేజీలో విశాలమైన లేఅవుట్‌ను ఉపయోగించండి','These options affect the thank you page, view order details on account pages and on email notifications.' => 'ఈ ఎంపికలు ధన్యవాదాల పేజీ, ఖాతా పేజీలలో ఆర్డర్ వివరాలను వీక్షించడం మరియు ఇమెయిల్ నోటిఫికేషన్‌లను ప్రభావితం చేస్తాయి.','Save settings' => 'సెట్టింగ్‌లను సేవ్ చేయండి','Docs' => 'డాక్స్','Cart' => 'బండి','Thank you' => 'ధన్యవాదాలు','Address autocomplete' => 'చిరునామా ఆటోకంప్లీట్','Trust badges' => 'ట్రస్ట్ బ్యాడ్జ్‌లు','You do not have permission to save these settings.' => 'ఈ సెట్టింగ్‌లను సేవ్ చేయడానికి మీకు అనుమతి లేదు.','Invalid save request.' => 'చెల్లని సేవ్ అభ్యర్థన.','Your settings have been saved.' => 'మీ సెట్టింగ్‌లు సేవ్ చేయబడ్డాయి.','Saving...' => 'సేవ్ అవుతోంది...','Settings could not be saved. Please try again.' => 'సెట్టింగ్‌లను సేవ్ చేయలేకపోయాము. దయచేసి మళ్ళీ ప్రయత్నించండి.','Dismiss notice' => 'నోటీసును కొట్టివేయండి','Open settings menu' => 'సెట్టింగ్స్ మెనూను తెరవండి','Close settings menu' => 'సెట్టింగ్‌ల మెనూను మూసివేయండి','Preview' => 'ప్రివ్యూ','Expand preview' => 'ప్రివ్యూను విస్తరించండి','Collapse preview' => 'ప్రివ్యూను కుదించండి','Show header and footer' => 'హెడర్ మరియు ఫుటర్ చూపించు','Hide header and footer' => 'హెడర్ మరియు ఫుటర్ ను దాచండి','Page preview' => 'పేజీ ప్రివ్యూ','Preview viewport' => 'ప్రివ్యూ వ్యూపోర్ట్','Tablet' => 'టాబ్లెట్','Desktop' => 'డెస్క్‌టాప్','Preview width' => 'ప్రివ్యూ వెడల్పు','Decrease width' => 'వెడల్పు తగ్గించండి','Preview width in pixels' => 'పిక్సెల్స్‌లో ప్రివ్యూ వెడల్పు','Increase width' => 'వెడల్పును పెంచండి','Preview as' => 'ప్రివ్యూగా','Guest' => 'అతిథి','Logged in' => 'లాగిన్ అయ్యారు','Preview page' => 'ప్రివ్యూ పేజీ','Expand preview for a closer look' => 'మరింత దగ్గరగా చూడటానికి ప్రివ్యూను విస్తరించండి','Available with %s.' => '%s తో అందుబాటులో ఉంది.','Turn them on' => 'వాటిని ఆన్ చేయండి','Optimizations for this page are turned off. %s to preview the page.' => 'ఈ పేజీకి సంబంధించిన ఆప్టిమైజేషన్‌లు నిలిపివేయబడ్డాయి. పేజీని ప్రివ్యూ చేయడానికి %s నొక్కండి.','%s preview' => '%s ప్రివ్యూ','Isolated session · nothing is saved' => 'వివిక్త సెషన్ · ఏదీ సేవ్ చేయబడలేదు','Usage tracking' => 'వినియోగ ట్రాకింగ్','Send non-sensitive site environment reports to help Fluid Checkout improve compatibility. Reports are not sent until enabled in the options below.' => 'ఫ్లూయిడ్ చెకౌట్ అనుకూలతను మెరుగుపరచడంలో సహాయపడటానికి, సున్నితత్వం లేని సైట్ వాతావరణ నివేదికలను పంపండి. దిగువ ఎంపికలలో ఎనేబుల్ చేసే వరకు నివేదికలు పంపబడవు.','Send usage tracking reports to Fluid Checkout' => 'ఫ్లూయిడ్ చెక్అవుట్‌కు వినియోగ ట్రాకింగ్ నివేదికలను పంపండి','These reports help us improve compatibility and support for your site and are sent weekly when enabled.' => 'ఈ నివేదికలు మీ సైట్ కోసం అనుకూలతను మరియు మద్దతును మెరుగుపరచడంలో మాకు సహాయపడతాయి మరియు ప్రారంభించినప్పుడు వారానికి ఒకసారి పంపబడతాయి.','No customer, admin user, or any other sensitive data is included in the reports.' => 'నివేదికలలో కస్టమర్, అడ్మిన్ యూజర్ లేదా మరే ఇతర సున్నితమైన డేటా చేర్చబడలేదు.','Basic environment info' => 'ప్రాథమిక పర్యావరణ సమాచారం','WordPress, PHP, WooCommerce, theme, and plugin list data. Always included when reporting is enabled. Helps us understand the environment your site is running in.' => 'వర్డ్‌ప్రెస్, PHP, WooCommerce, థీమ్ మరియు ప్లగిన్ జాబితా డేటా. రిపోర్టింగ్ ఎనేబుల్ చేసినప్పుడు ఇది ఎల్లప్పుడూ చేర్చబడుతుంది. మీ సైట్ ఏ వాతావరణంలో నడుస్తుందో అర్థం చేసుకోవడానికి ఇది మాకు సహాయపడుతుంది.','Plugin settings' => 'ప్లగిన్ సెట్టింగ్‌లు','Sends Fluid Checkout plugin settings to help with support requests and helps us understand how you are using our plugins.' => 'సపోర్ట్ అభ్యర్థనలకు సహాయపడటానికి ఫ్లూయిడ్ చెక్అవుట్ ప్లగిన్ సెట్టింగ్‌లను పంపుతుంది మరియు మీరు మా ప్లగిన్‌లను ఎలా ఉపయోగిస్తున్నారో అర్థం చేసుకోవడానికి మాకు సహాయపడుతుంది.','Coming soon' => 'త్వరలో వస్తుంది','Sales metrics' => 'అమ్మకాల కొలమానాలు','Monthly order count and total sales for one year prior to installing Fluid Checkout up to today. Helps us understand if you are making more money with our plugins installed. No customer or user data is ever sent.' => 'ఫ్లూయిడ్ చెక్అవుట్‌ను ఇన్‌స్టాల్ చేయడానికి ముందు ఒక సంవత్సరం నుండి నేటి వరకు నెలవారీ ఆర్డర్ల సంఖ్య మరియు మొత్తం అమ్మకాలు. మా ప్లగిన్‌లను ఇన్‌స్టాల్ చేయడం ద్వారా మీరు ఎక్కువ డబ్బు సంపాదిస్తున్నారో లేదో అర్థం చేసుకోవడానికి ఇది మాకు సహాయపడుతుంది. కస్టమర్ లేదా వినియోగదారు డేటా ఏదీ ఎప్పుడూ పంపబడదు.','Utilities' => 'యుటిలిటీలు','Use <code>TomSelect</code> dropdown components instead of <code>select2</code>' => '<code>select2</code> బదులుగా <code>TomSelect</code> డ్రాప్‌డౌన్ కాంపోనెంట్‌లను ఉపయోగించండి','TomSelect is a simpler dropdown selection component which is less prone to errors than Select2, while offering the same functionality.' => 'TomSelect అనేది ఒక సరళమైన డ్రాప్‌డౌన్ ఎంపిక కాంపోనెంట్, ఇది Select2 కంటే తక్కువ లోపాలకు గురవుతుంది, అదే సమయంలో అవే కార్యాచరణను అందిస్తుంది.','Sets the font size inside form fields to 16px on pages optimized by this plugin to avoid automatically zooming in when interacting with form fields on small devices.' => 'ఈ ప్లగిన్ ద్వారా ఆప్టిమైజ్ చేయబడిన పేజీలలో, చిన్న పరికరాలలో ఫారమ్ ఫీల్డ్‌లతో ఇంటరాక్ట్ అయ్యేటప్పుడు ఆటోమేటిక్‌గా జూమ్ అవ్వడాన్ని నివారించడానికి, ఫారమ్ ఫీల్డ్‌ల లోపల ఫాంట్ సైజును 16pxకు సెట్ చేస్తుంది.','Safari and other browsers might automatically zoom in on mobile devices to make the text easier to read when the font size is smaller than 16px.' => 'ఫాంట్ సైజు 16px కంటే తక్కువగా ఉన్నప్పుడు, మొబైల్ పరికరాలలో టెక్స్ట్‌ను సులభంగా చదవడానికి వీలుగా సఫారి మరియు ఇతర బ్రౌజర్‌లు ఆటోమేటిక్‌గా జూమ్ చేయవచ్చు.','Enable script processing tracking on the browser console.' => 'బ్రౌజర్ కన్సోల్‌లో స్క్రిప్ట్ ప్రాసెసింగ్ ట్రాకింగ్‌ను ఎనేబుల్ చేయండి.','Unminified assets' => 'అన్‌మినిఫైడ్ ఆస్తులు','Google Maps scripts' => 'గూగుల్ మ్యాప్స్ స్క్రిప్ట్‌లు','Do not remove duplicate Google Maps scripts' => 'నకిలీ Google Maps స్క్రిప్ట్‌లను తొలగించవద్దు','When enabled, duplicate Google Maps scripts will NOT be removed which can cause errors and performance issues. Only use this option while troubleshooting.' => 'దీన్ని ఎనేబుల్ చేసినప్పుడు, డూప్లికేట్ గూగుల్ మ్యాప్స్ స్క్రిప్ట్‌లు తొలగించబడవు, దీనివల్ల ఎర్రర్‌లు మరియు పనితీరు సమస్యలు తలెత్తవచ్చు. ట్రబుల్షూటింగ్ చేసేటప్పుడు మాత్రమే ఈ ఆప్షన్‌ను ఉపయోగించండి.','Widget areas' => 'విడ్జెట్ ప్రాంతాలు','Last step on mobile' => 'మొబైల్‌లో చివరి దశ','Display widgets only at last step on mobile' => 'మొబైల్‌లో చివరి దశలో మాత్రమే విడ్జెట్‌లను ప్రదర్శించండి','Display checkout trust badge widgets only when viewing the last checkout step on mobile devices' => 'మొబైల్ పరికరాలలో చివరి చెక్అవుట్ దశను చూస్తున్నప్పుడు మాత్రమే చెక్అవుట్ ట్రస్ట్ బ్యాడ్జ్ విడ్జెట్‌లను ప్రదర్శించండి','Standard' => 'ప్రామాణికం','VAT number field' => 'VAT సంఖ్య ఫీల్డ్','Add a VAT number field to the billing form.' => 'బిల్లింగ్ ఫారమ్‌కు VAT నంబర్ ఫీల్డ్‌ను జోడించండి.','Field label' => 'ఫీల్డ్ లేబుల్','Set the label of the VAT number field (ie. VAT number). On multi-language websites, it is better to leave this field empty and translate the original string.' => 'VAT నంబర్ ఫీల్డ్ యొక్క లేబుల్‌ను (అంటే, VAT నంబర్) సెట్ చేయండి. బహుళ భాషా వెబ్‌సైట్‌లలో, ఈ ఫీల్డ్‌ను ఖాళీగా వదిలి, అసలు స్ట్రింగ్‌ను అనువదించడం మంచిది.','VAT Number' => 'వ్యాట్ నంబర్','EU-VAT' => 'EU-VAT','Enable the VAT number field to see more options' => 'మరిన్ని ఎంపికలను చూడటానికి VAT నంబర్ ఫీల్డ్‌ను ఎనేబుల్ చేయండి','VAT validation' => 'వ్యాట్ ధ్రువీకరణ','Validate VAT number field for EU-VAT during checkout' => 'చెక్అవుట్ సమయంలో EU-VAT కోసం VAT నంబర్ ఫీల్డ్‌ను ధృవీకరించండి','Checks if the VAT Number provided is a valid VAT number registered on the European VIES Database (VAT Information Exchange System).' => 'అందించిన VAT నంబర్, యూరోపియన్ VIES డేటాబేస్ (VAT సమాచార మార్పిడి వ్యవస్థ)లో నమోదు చేయబడిన చెల్లుబాటు అయ్యే VAT నంబర్ అవునో కాదో తనిఖీ చేస్తుంది.','Shop VAT number' => 'షాప్ VAT నంబర్','The shop\'s VAT number used for requesting EU-VAT validation, and printed on invoices. <br><strong>We strongly recommend adding your Shop VAT number</strong> as otherwise the VIES consultation results might not be valid for accounting purposes. <br>Ie.: <code>ATU99999999</code> or <code>EE999999999</code>.' => 'EU-VAT ధ్రువీకరణను అభ్యర్థించడానికి ఉపయోగించే మరియు ఇన్‌వాయిస్‌లపై ముద్రించబడే షాప్ VAT నంబర్.<br> <strong>మీ షాప్ VAT నంబర్‌ను జోడించాలని మేము గట్టిగా సిఫార్సు చేస్తున్నాము,</strong> లేకపోతే VIES సంప్రదింపుల ఫలితాలు అకౌంటింగ్ ప్రయోజనాల కోసం చెల్లుబాటు కాకపోవచ్చు.<br> అనగా.: <code>ATU99999999</code> లేదా <code>EE999999999</code> .','Reverse charge' => 'రివర్స్ ఛార్జ్','Apply reverse charge mechanism' => 'రివర్స్ ఛార్జ్ మెకానిజంను వర్తింపజేయండి','Set tax rate to zero and display "Reverse charge" on invoices when the customer\'s VAT number is valid. A different "Reverse charge" text might be required depending on the store\'s country.' => 'కస్టమర్ యొక్క VAT నంబర్ చెల్లుబాటులో ఉన్నప్పుడు, పన్ను రేటును సున్నాకు సెట్ చేసి, ఇన్‌వాయిస్‌లపై &quot;రివర్స్ ఛార్జ్&quot; అని ప్రదర్శించండి. స్టోర్ ఉన్న దేశాన్ని బట్టి వేరే &quot;రివర్స్ ఛార్జ్&quot; టెక్స్ట్ అవసరం కావచ్చు.','Same country' => 'అదే దేశం','Apply reverse charge mechanism for transactions in the shop country:' => 'దుకాణం ఉన్న దేశంలోని లావాదేవీలకు రివర్స్ ఛార్జ్ విధానాన్ని వర్తింపజేయండి:','Enables applying reverse charge mechanism for transactions between companies in the same country as the shop.' => 'దుకాణం ఉన్న దేశంలోని కంపెనీల మధ్య జరిగే లావాదేవీలకు రివర్స్ ఛార్జ్ విధానాన్ని వర్తింపజేయడానికి వీలు కల్పిస్తుంది.','Reverse charge exceptions' => 'రివర్స్ ఛార్జ్ మినహాయింపులు','Select additional countries to skip applying the reverse charge mechanism.' => 'రివర్స్ ఛార్జ్ విధానాన్ని వర్తింపజేయకుండా ఉండటానికి అదనపు దేశాలను ఎంచుకోండి.','Taxes will be charged to orders from these countries even when a valid VAT number is provided.' => 'చెల్లుబాటు అయ్యే VAT నంబర్ అందించినప్పటికీ, ఈ దేశాల నుండి వచ్చే ఆర్డర్‌లపై పన్నులు విధించబడతాయి.','Reverse charge label on invoices' => 'ఇన్‌వాయిస్‌లపై రివర్స్ ఛార్జ్ లేబుల్','Set the label of "reverse charge" on the checkout page and order details.' => 'చెక్‌అవుట్ పేజీ మరియు ఆర్డర్ వివరాలపై &quot;రివర్స్ ఛార్జ్&quot; అనే లేబుల్‌ను సెట్ చేయండి.','Reverse charge text on invoices' => 'ఇన్‌వాయిస్‌లపై రివర్స్ ఛార్జ్ టెక్స్ట్','Set the label of "reverse charge" text on invoices.' => 'ఇన్‌వాయిస్‌లపై &quot;రివర్స్ ఛార్జ్&quot; అనే లేబుల్ టెక్స్ట్‌ను సెట్ చేయండి.','Tax to be paid on reverse charge basis' => 'రివర్స్ ఛార్జ్ పద్ధతిలో పన్ను చెల్లించాలి','Company name' => 'కంపెనీ పేరు','Autocomplete company name from VAT number' => 'VAT నంబర్ నుండి కంపెనీ పేరును ఆటోకంప్లీట్ చేయండి','Fill in the billing company name based on the valid VAT number provided by the customer.' => 'కస్టమర్ అందించిన చెల్లుబాటు అయ్యే VAT నంబర్ ఆధారంగా బిల్లింగ్ కంపెనీ పేరును పూరించండి.','Company name editing' => 'కంపెనీ పేరు సవరణ','Allow editing of auto-filled company name' => 'స్వయంచాలకంగా నింపబడిన కంపెనీ పేరును సవరించడానికి అనుమతించండి','When enabled, customers can change the company name associated with the provided VAT number.' => 'ఎనేబుల్ చేసినప్పుడు, కస్టమర్‌లు అందించిన VAT నంబర్‌తో అనుబంధించబడిన కంపెనీ పేరును మార్చుకోవచ్చు.','EU-VAT for digital goods' => 'డిజిటల్ వస్తువులపై EU-VAT','From January 1st, 2015, modifications have been made to the EU VAT regulations concerning digital goods, impacting exclusively B2C transactions. The VAT on digital goods must be calculated based on the customer\'s location, and evidence of this needs to be collected (IP address and billing address).' => 'జనవరి 1, 2015 నుండి, డిజిటల్ వస్తువులకు సంబంధించిన EU VAT నిబంధనలలో మార్పులు చేయబడ్డాయి, ఇవి ప్రత్యేకంగా B2C లావాదేవీలను ప్రభావితం చేస్తాయి. డిజిటల్ వస్తువులపై VATని కస్టమర్ ఉన్న ప్రదేశం ఆధారంగా లెక్కించాలి, మరియు దీనికి సంబంధించిన రుజువును (IP చిరునామా మరియు బిల్లింగ్ చిరునామా) సేకరించాల్సి ఉంటుంది.','Tax classes for digital goods' => 'డిజిటల్ వస్తువుల పన్ను వర్గాలు','Select some tax classes' => 'కొన్ని పన్ను తరగతులను ఎంచుకోండి','Location evidence' => 'స్థాన సాక్ష్యం','Collect customer\'s location evidence' => 'కస్టమర్ యొక్క లొకేషన్ సాక్ష్యాలను సేకరించండి','Saves the IP address and validate it against the customer\'s billing address. Customer\'s must confirm their billing address by checking a checkbox on the checkout page if the country from their billing address and IP do not match.' => 'IP చిరునామాను సేవ్ చేసి, దానిని కస్టమర్ యొక్క బిల్లింగ్ చిరునామాతో సరిపోల్చి ధృవీకరిస్తుంది. ఒకవేళ వారి బిల్లింగ్ చిరునామాలోని దేశం మరియు IP సరిపోలకపోతే, కస్టమర్లు చెక్అవుట్ పేజీలోని చెక్‌బాక్స్‌ను ఎంచుకోవడం ద్వారా వారి బిల్లింగ్ చిరునామాను తప్పనిసరిగా నిర్ధారించుకోవాలి.','This option is managed in Fluid Checkout. <a href="%s">Change it in Customer accounts settings</a>.' => 'ఈ ఎంపిక ఫ్లూయిడ్ చెక్అవుట్‌లో నిర్వహించబడుతుంది. <a href="%s">కస్టమర్ ఖాతాల సెట్టింగ్‌లలో దీన్ని మార్చండి</a> .','This option is managed in Fluid Checkout. Change it under Fluid Checkout > Customer accounts.' => 'ఈ ఎంపిక ఫ్లూయిడ్ చెక్అవుట్‌లో నిర్వహించబడుతుంది. ఫ్లూయిడ్ చెక్అవుట్ &gt; కస్టమర్ ఖాతాల కింద దీన్ని మార్చండి.','This option is managed in Fluid Checkout. The shipping destination is always set to "Default to customer shipping address" when Fluid Checkout is activated. Customers can still provide different shipping and billing addresses during checkout.<br><br>An option for setting the default billing address to be the same as the shipping address is available in the <a href="%s">Fluid Checkout settings</a>.' => 'ఈ ఎంపిక ఫ్లూయిడ్ చెక్అవుట్‌లో నిర్వహించబడుతుంది. ఫ్లూయిడ్ చెక్అవుట్ యాక్టివేట్ చేయబడినప్పుడు, షిప్పింగ్ గమ్యస్థానం ఎల్లప్పుడూ &quot;కస్టమర్ షిప్పింగ్ చిరునామాకు డిఫాల్ట్&quot;గా సెట్ చేయబడి ఉంటుంది. అయినప్పటికీ, కస్టమర్‌లు చెక్అవుట్ సమయంలో వేర్వేరు షిప్పింగ్ మరియు బిల్లింగ్ చిరునామాలను అందించవచ్చు.<br><br> <a href="%s">ఫ్లూయిడ్ చెక్అవుట్ సెట్టింగ్స్‌లో</a> , డిఫాల్ట్ బిల్లింగ్ చిరునామాను షిప్పింగ్ చిరునామా వలెనే సెట్ చేసుకునే ఆప్షన్ అందుబాటులో ఉంది.','This option is managed in Fluid Checkout. The shipping destination is always set to "Default to customer shipping address" when Fluid Checkout is activated. Customers can still provide different shipping and billing addresses during checkout.<br><br>An option for setting the default billing address to be the same as the shipping address is available at WooCommerce > Settings > Fluid Checkout.' => 'ఈ ఎంపిక ఫ్లూయిడ్ చెక్అవుట్‌లో నిర్వహించబడుతుంది. ఫ్లూయిడ్ చెక్అవుట్ యాక్టివేట్ చేయబడినప్పుడు, షిప్పింగ్ గమ్యస్థానం ఎల్లప్పుడూ &quot;కస్టమర్ షిప్పింగ్ చిరునామాకు డిఫాల్ట్&quot;గా సెట్ చేయబడి ఉంటుంది. అయినప్పటికీ, కస్టమర్‌లు చెక్అవుట్ సమయంలో వేర్వేరు షిప్పింగ్ మరియు బిల్లింగ్ చిరునామాలను అందించవచ్చు.<br><br> WooCommerce &gt; సెట్టింగ్‌లు &gt; ఫ్లూయిడ్ చెక్అవుట్‌లో, డిఫాల్ట్ బిల్లింగ్ చిరునామాను షిప్పింగ్ చిరునామా వలెనే సెట్ చేయడానికి ఒక ఎంపిక అందుబాటులో ఉంది.','These settings have been moved to WP Admin > Fluid Checkout > Settings.' => 'ఈ సెట్టింగ్‌లు WP Admin &gt; Fluid Checkout &gt; Settingsకు తరలించబడ్డాయి.','This WooCommerce Settings tab is deprecated and will be removed in Fluid Checkout 6.0.' => 'ఈ WooCommerce సెట్టింగ్స్ ట్యాబ్ వాడుకలో లేదు మరియు Fluid Checkout 6.0లో తీసివేయబడుతుంది.','Go to settings page' => 'సెట్టింగ్స్ పేజీకి వెళ్లండి','Hide this tab permanently' => 'ఈ ట్యాబ్‌ను శాశ్వతంగా దాచండి','Site report preview' => 'సైట్ నివేదిక ప్రివ్యూ','This is the data that would be included in the next site environment report based on your current settings.' => 'మీ ప్రస్తుత సెట్టింగ్‌ల ఆధారంగా తదుపరి సైట్ ఎన్విరాన్‌మెంట్ రిపోర్ట్‌లో చేర్చబడే డేటా ఇది.','Loading report preview...' => 'నివేదిక ప్రివ్యూ లోడ్ అవుతోంది...','Could not load the site report preview. Try again.' => 'సైట్ నివేదిక ప్రివ్యూను లోడ్ చేయలేకపోయాము. మళ్ళీ ప్రయత్నించండి.','Could not send the site report. Try again.' => 'సైట్ రిపోర్ట్‌ను పంపలేకపోయాము. మళ్ళీ ప్రయత్నించండి.','Site report sent successfully.' => 'సైట్ నివేదిక విజయవంతంగా పంపబడింది.','Enable and send now' => 'ఇప్పుడే ప్రారంభించి పంపండి','Close' => 'మూసివేయండి','A site report request is already in progress. Try again in a moment.' => 'సైట్ నివేదిక అభ్యర్థన ఇప్పటికే ప్రక్రియలో ఉంది. కాసేపటి తర్వాత మళ్ళీ ప్రయత్నించండి.','Site environment reporting is disabled.' => 'సైట్ వాతావరణ నివేదన నిలిపివేయబడింది.','No site report data is available to send.' => 'పంపడానికి సైట్ నివేదిక డేటా ఏదీ అందుబాటులో లేదు.','This site domain cannot send environment reports (local or development domains are excluded).' => 'ఈ సైట్ డొమైన్ పర్యావరణ నివేదికలను పంపలేదు (స్థానిక లేదా అభివృద్ధి డొమైన్‌లు మినహాయించబడ్డాయి).','A site report was sent recently. Try again later.' => 'ఇటీవల ఒక సైట్ నివేదిక పంపబడింది. తర్వాత మళ్ళీ ప్రయత్నించండి.','The site report could not be sent. Try again later.' => 'సైట్ నివేదికను పంపడం సాధ్యపడలేదు. దయచేసి తర్వాత మళ్ళీ ప్రయత్నించండి.','Site environment reporting is not available.' => 'సైట్ వాతావరణ నివేదిక అందుబాటులో లేదు.','No site report data is available for the selected settings.' => 'ఎంచుకున్న సెట్టింగ్‌ల కోసం సైట్ నివేదిక డేటా అందుబాటులో లేదు.','You are not allowed to manage site reports.' => 'మీకు సైట్ నివేదికలను నిర్వహించే అనుమతి లేదు.','PRO feature' => 'ప్రో ఫీచర్','Other plugins' => 'ఇతర ప్లగిన్‌లు','Get only this add-on &mdash; %s' => 'ఈ యాడ్-ఆన్‌ను మాత్రమే పొందండి — %s','Install add-on' => 'యాడ్-ఆన్‌ను ఇన్‌స్టాల్ చేయండి','Upgrade to PRO &mdash; %s' => 'PRO కి అప్‌గ్రేడ్ చేయండి — %s','<a target="_blank" href="%1$s">Get %2$s</a> to unlock these options.' => 'ఈ ఎంపికలను అన్‌లాక్ చేయడానికి <a target="_blank" href="%1$s">%2$లను పొందండి</a> .','Add-on' => 'యాడ్-ఆన్','View documentation' => 'డాక్యుమెంటేషన్‌ను వీక్షించండి','Requests require a logged-in WordPress user. Omit user_id to use the current user\'s data, or pass user_id to target another account when the caller can edit that user (edit_user capability). Unauthenticated requests return fc_api_forbidden. An invalid user_id returns fc_api_user_not_found.' => 'అభ్యర్థనలకు లాగిన్ అయిన వర్డ్‌ప్రెస్ వినియోగదారు అవసరం. ప్రస్తుత వినియోగదారు డేటాను ఉపయోగించడానికి user_idని వదిలివేయండి, లేదా కాల్ చేసేవారు ఆ వినియోగదారుని సవరించగలిగినప్పుడు (edit_user సామర్థ్యం) వేరొక ఖాతాను లక్ష్యంగా చేసుకోవడానికి user_idని పంపండి. ప్రామాణీకరణ లేని అభ్యర్థనలు fc_api_forbiddenను తిరిగి ఇస్తాయి. చెల్లని user_id fc_api_user_not_foundను తిరిగి ఇస్తుంది.','HTTP 200 with { "data": { ... } } when the handler returns a payload.' => 'హ్యాండ్లర్ పేలోడ్‌ను తిరిగి ఇచ్చినప్పుడు HTTP 200 with { &quot;data&quot;: { ... } }.','HTTP 200 with { "success": true } when there is no payload (for example DELETE).' => 'పేలోడ్ లేనప్పుడు (ఉదాహరణకు DELETE) HTTP 200 with { &quot;success&quot;: true }.','Failures return WordPress REST error JSON from WP_Error (code, message, data.status). Wire codes use the fc_api_* prefix.' => 'వైఫల్యాలు WP_Error నుండి WordPress REST ఎర్రర్ JSONను (కోడ్, సందేశం, డేటా.స్టేటస్) తిరిగి ఇస్తాయి. వైర్ కోడ్‌లు fc_api_* ప్రిఫిక్స్‌ను ఉపయోగిస్తాయి.','Forbidden access.' => 'ప్రవేశం నిషేధించబడింది.','Target user was not found.' => 'లక్షిత వినియోగదారుడు కనుగొనబడలేదు.','This feature is not available.' => 'ఈ ఫీచర్ అందుబాటులో లేదు.','A required address field is missing.' => 'అవసరమైన చిరునామా ఫీల్డ్ లేదు.','Postcode or ZIP is invalid.' => 'పోస్ట్‌కోడ్ లేదా జిప్ చెల్లదు.','Phone number is invalid.' => 'ఫోన్ నంబర్ చెల్లదు.','State or county is invalid.' => 'రాష్ట్రం లేదా కౌంటీ చెల్లదు.','Country is invalid or has no address fields.' => 'దేశం చెల్లనిది లేదా చిరునామా ఫీల్డ్‌లు లేవు.','The request could not be processed.' => 'అభ్యర్థనను ప్రాసెస్ చేయలేకపోయింది.','Back to previous step' => 'మునుపటి దశకు తిరిగి వెళ్లండి','Skip to settings' => 'సెట్టింగ్‌లకు వెళ్లండి','Start over and return to the first guided setup step' => 'మళ్లీ మొదటి నుండి ప్రారంభించి, మొదటి గైడెడ్ సెటప్ దశకు తిరిగి వెళ్లండి.','Start over' => 'మళ్ళీ మొదలుపెట్టండి','Please complete all sub-steps before continuing.' => 'దయచేసి కొనసాగే ముందు అన్ని ఉప-దశలను పూర్తి చేయండి.','Expand' => 'విస్తరించండి','Collapse' => 'కుప్పకూలండి','Skip' => 'దాటవేయి','Mark as complete' => 'పూర్తయినట్లుగా గుర్తించండి','Mark as incomplete' => 'అసంపూర్ణంగా గుర్తించండి','View full-size image: %s' => 'పూర్తి పరిమాణ చిత్రాన్ని వీక్షించండి: %s','Full-size setup guide image' => 'పూర్తి-పరిమాణ సెటప్ గైడ్ చిత్రం','Close image' => 'చిత్రాన్ని మూసివేయండి','Fluid Checkout Guided Setup' => 'ఫ్లూయిడ్ చెక్అవుట్ గైడెడ్ సెటప్','Welcome' => 'స్వాగతం','Explore your checkout' => 'మీ చెక్అవుట్‌ను అన్వేషించండి','All set' => 'అంతా సిద్ధం','You do not have permission to access this page.' => 'ఈ పేజీని యాక్సెస్ చేయడానికి మీకు అనుమతి లేదు.','Go to step %1$d: %2$s' => 'దశ %1$d: %2$s కు వెళ్ళండి','This guided setup helps you get familiar with Fluid Checkout. The steps below are placeholders for now.' => 'ఈ గైడెడ్ సెటప్ మీకు ఫ్లూయిడ్ చెకౌట్‌తో పరిచయం ఏర్పరచుకోవడానికి సహాయపడుతుంది. కింద ఉన్న దశలు ప్రస్తుతానికి తాత్కాలికమైనవి.','Continue to the next step when you are ready.' => 'మీరు సిద్ధంగా ఉన్నప్పుడు తదుపరి దశకు వెళ్లండి.','Open your store checkout to see Fluid Checkout in action.' => 'ఫ్లూయిడ్ చెక్అవుట్ ఎలా పనిచేస్తుందో చూడటానికి మీ స్టోర్ చెక్అవుట్‌ను తెరవండి.','View checkout page' => 'చెక్అవుట్ పేజీని వీక్షించండి','You can return to Fluid Checkout settings to continue configuring your store.' => 'మీ స్టోర్‌ను కాన్ఫిగర్ చేయడం కొనసాగించడానికి మీరు ఫ్లూయిడ్ చెక్అవుట్ సెట్టింగ్‌లకు తిరిగి వెళ్లవచ్చు.','Review checkout and cart settings' => 'చెక్అవుట్ మరియు కార్ట్ సెట్టింగ్‌లను సమీక్షించండి','Explore add-ons from the dashboard' => 'డాష్‌బోర్డ్ నుండి యాడ్-ఆన్‌లను అన్వేషించండి','Finish & go to settings' => 'పూర్తి చేసి సెట్టింగ్‌లకు వెళ్లండి','Update the billing phone field visibility option from the legacy value to match WooCommerce conventions.' => 'WooCommerce నియమాలకు సరిపోయేలా, బిల్లింగ్ ఫోన్ ఫీల్డ్ విజిబిలిటీ ఆప్షన్‌ను పాత విలువ నుండి అప్‌డేట్ చేయండి.','Update the shipping phone field visibility option from the legacy value to match WooCommerce conventions.' => 'WooCommerce నియమాలకు సరిపోయేలా, షిప్పింగ్ ఫోన్ ఫీల్డ్ విజిబిలిటీ ఆప్షన్‌ను పాత విలువ నుండి అప్‌డేట్ చేయండి.','Copy the order summary background color setting to the new Split design secondary column background color option.' => 'ఆర్డర్ సారాంశం బ్యాక్‌గ్రౌండ్ కలర్ సెట్టింగ్‌ను కొత్త స్ప్లిట్ డిజైన్ సెకండరీ కాలమ్ బ్యాక్‌గ్రౌండ్ కలర్ ఆప్షన్‌కు కాపీ చేయండి.','The enhanced select fields feature is always disabled when using the Biteship plugin.' => 'బైట్‌షిప్ ప్లగిన్‌ను ఉపయోగిస్తున్నప్పుడు మెరుగైన సెలెక్ట్ ఫీల్డ్స్ ఫీచర్ ఎల్లప్పుడూ డిసేబుల్ చేయబడి ఉంటుంది.','The place order position is always set to "Below the order summary" when using German Market. That plugin requires the place order button and legal checkboxes to be displayed below the order summary.' => 'జర్మన్ మార్కెట్‌ను ఉపయోగిస్తున్నప్పుడు, ఆర్డర్ పెట్టే స్థానం ఎల్లప్పుడూ &quot;ఆర్డర్ సారాంశం క్రింద&quot; అని సెట్ చేయబడి ఉంటుంది. ఆ ప్లగిన్‌కు, ఆర్డర్ పెట్టే బటన్ మరియు చట్టపరమైన చెక్‌బాక్స్‌లు ఆర్డర్ సారాంశం క్రింద ప్రదర్శించబడటం అవసరం.','The place order position is always set to "Below the order summary" when using Germanized for WooCommerce. That plugin requires the place order button and legal checkboxes to be displayed below the order summary.' => 'Germanized for WooCommerceను ఉపయోగిస్తున్నప్పుడు, ఆర్డర్ పెట్టే స్థానం ఎల్లప్పుడూ &quot;ఆర్డర్ సారాంశం క్రింద&quot;కు సెట్ చేయబడి ఉంటుంది. ఆ ప్లగిన్‌కు, ఆర్డర్ పెట్టే బటన్ మరియు చట్టపరమైన చెక్‌బాక్స్‌లు ఆర్డర్ సారాంశం క్రింద ప్రదర్శించబడాలి.','Edit pickup locations' => 'పికప్ స్థానాలను సవరించండి','Use local pickup label from WooCommerce settings' => 'WooCommerce సెట్టింగ్‌ల నుండి స్థానిక పికప్ లేబుల్‌ను ఉపయోగించండి','When enabled, the pickup option label on checkout matches the title from WooCommerce pickup location settings. When disabled, the label uses the translatable "Local pickup" text from Fluid Checkout.' => 'ఎనేబుల్ చేసినప్పుడు, చెక్అవుట్‌లోని పికప్ ఆప్షన్ లేబుల్, WooCommerce పికప్ లొకేషన్ సెట్టింగ్‌లలోని టైటిల్‌తో సరిపోలుతుంది. డిసేబుల్ చేసినప్పుడు, ఆ లేబుల్ Fluid Checkout నుండి అనువదించదగిన &quot;Local pickup&quot; టెక్స్ట్‌ను ఉపయోగిస్తుంది.','Button label for applying coupon codesApply' => 'వర్తించు','Checkout step titleContact' => 'సంప్రదించండి','Checkout step titleShipping' => 'షిప్పింగ్','Checkout step titleBilling' => 'బిల్లింగ్','Checkout step titlePayment' => 'చెల్లింపు','Checkout substep change link labelChange' => 'మార్చు','Checkout substep save link labelSave changes' => 'మార్పులను సేవ్ చేయి','Substep review textNone.' => 'ఏదీ లేదు.','Substep review field format%1$s' => '%1$s','Substep review field format: with label%2$s: %1$s' => '%2$లు: %1$లు','Image uploader.No image selected.' => 'ఏ చిత్రం ఎంచుకోబడలేదు.','Settings sectionCart' => 'కార్ట్','Settings sectionOrder pay' => 'ఆర్డర్ పే','Settings sectionThank you' => 'ధన్యవాదాలు','Settings section titleIntegrations' => 'ఇంటిగ్రేషన్లు','Settings section titleLicense key